        "fileContentHash": "5c5f1dc184cf9ceff10c1e710c20dfbb50a1c20fa459d06a5538bedd54c1602f",
        "sourceSlice": "class ForgeAuthError extends Error {\n  code: ForgeAuthDiagnosticCode;\n  status: number;\n\n  constructor(\n    code: ForgeAuthDiagnosticCode,\n    message: string,\n    options: { status?: number; cause?: unknown } = {},\n  ) {\n    super(message);\n    this.name = \"ForgeAuthError\";\n    this.code = code;\n    this.status = options.status ?? 401;\n    if (options.cause !== undefined) {\n      this.cause = options.cause;\n    }\n  }\n}"
