        "sourceSlice": "function addSignalIfOverlap(\n  signals: DeltaWorkSessionSignal[],\n  signal: string,\n  weight: number,\n  left: string[],\n  right: string[],\n): void {\n  const value = left.find((item) => right.includes(item));\n  if (value) {\n    signals.push({ signal, weight, value });\n  }\n}"
