        "sourceSlice": "function all<T, E>(results: ReadonlyArray<Result<T, E>>): Result<T[], E> {\n  const values: T[] = [];\n  for (const result of results) {\n    if (!result.ok) {\n      return result;\n    }\n    values.push(result.value);\n  }\n  return ok(values);\n}"
