      "meta": {
        "exportPath": "",
        "fileContentHash": "50f21501658975eda61b01ed85aa24ec25c46eafc70de7236f30a08e635cabfe",
        "sourceSlice": "async function applyRlsSqlIfPostgres(\n  adapter: Awaited<ReturnType<typeof createDbAdapter>>[\"adapter\"],\n  workspaceRoot: string,\n): Promise<Diagnostic[]> {\n  const diagnostics: Diagnostic[] = [];\n  if (!adapter || adapter.kind !== \"postgres\") {\n    return diagnostics;\n  }\n\n  const sql = readGeneratedText(workspaceRoot, `${GENERATED_DIR}/rlsPolicies.sql`);\n  if (!sql) {\n    return diagnostics;\n  }\n\n  try {\n    for (const statement of splitSqlStatements(sql)) {\n      await adapter.query(statement);\n    }\n  } catch (error) {\n    diagnostics.push(\n      createDiagnostic({\n        severity: \"error\",\n        code: FORGE_RLS_APPLY_FAILED,\n        message: error instanceof Error ? error.message : \"failed to apply RLS policies\",\n      }),\n    );\n  }\n\n  return diagnostics;\n}"
      },
