        "sourceSlice": "function augmentEnvSchemaWithAuthVars(schema: EnvSchema): EnvSchema {\n  const byName = new Map(schema.variables.map((variable) => [variable.name, variable]));\n  for (const name of [\n    AUTH_ENV.mode,\n    AUTH_ENV.issuer,\n    AUTH_ENV.audience,\n    AUTH_ENV.jwksUri,\n    AUTH_ENV.algorithms,\n  ]) {\n    if (!byName.has(name)) {\n      byName.set(name, {\n        name,\n        kind: \"config\",\n        required: false,\n        source: \"auth\",\n      });\n    }\n  }\n  return {\n    variables: [...byName.values()].sort((a, b) => a.name.localeCompare(b.name)),\n  };\n}"
