        "sourceSlice": "function authFromExternalPolicy(policy: string | undefined): CommandAuthBinding[\"auth\"] {\n  if (!policy) {\n    return { kind: \"public\" };\n  }\n  if (policy === \"public\" || policy === \"system\" || policy === \"user\") {\n    return { kind: policy };\n  }\n  return { kind: \"policy\", policy };\n}"
