        "sourceSlice": "function buildConfigRegistry(registry: SecretRegistry): ConfigRegistry {\n  const configs = registry.secrets\n    .filter((entry) => entry.public || !entry.required)\n    .map((entry) => ({\n      name: entry.name,\n      required: entry.required,\n      source: entry.source,\n      integration: entry.integration,\n    }));\n\n  return {\n    configs: configs.sort((a, b) => a.name.localeCompare(b.name)),\n  };\n}"
