        "sourceSlice": "function buildCreateTableSql(tableName: string, columns: ColumnDef[]): string {\n  const rendered = columns.map(renderColumn).join(\", \");\n  return `CREATE TABLE IF NOT EXISTS ${quoteIdent(tableName)} (${rendered})`;\n}"
