        "sourceSlice": "function buildForeignKeyIndexes(tableName: string, columns: ColumnDef[]): IndexDef[] {\n  const indexes: IndexDef[] = [];\n\n  for (const column of columns) {\n    if (column.references) {\n      indexes.push({\n        name: `idx_${tableName}_${column.name}`,\n        table: tableName,\n        columns: [column.name],\n      });\n    }\n  }\n\n  return indexes;\n}"
