      "id": "40913268d5ae92af8434b15a5002bedf9e3623a19e161fad3e3e902cef568a88",
      "kind": "code.function",
      "meta": {
        "exportPath": "export",
        "fileContentHash": "33acb6d7e1fbfeab83bb9772d9025b2b84aaee41b97e36bc6b0741c0ec829afc",
        "sourceSlice": "function buildManifestFileHashes(plan: EmitPlan): Record<string, string> {\n  const hashes: Record<string, string> = {};\n  const exportPaths = plan.files.map((file) => file.path);\n\n  for (const file of plan.files) {\n    hashes[file.path] = hashStable(renderBody(file));\n  }\n\n  const barrelBody = buildBarrelIndexBody(exportPaths);\n  hashes[BARREL_INDEX_PATH] = hashStable(barrelBody);\n  hashes[FORGE_LOCK_PATH] = hashStable(serializeForgeLock(plan.lock));\n\n  return hashes;\n}"
      },
      "name": "buildManifestFileHashes",
      "qualifiedName": "buildManifestFileHashes",
