      "id": "62ff2e2582147fc58587a2e56402705e8123e3f86bc5ebb75e4a917d867c1a2b",
      "kind": "code.function",
      "meta": {
        "exportPath": "",
        "fileContentHash": "511a071e355d2bae7caae4f678008acd61e2cea008edea32328d556643fedd79",
        "sourceSlice": "function buildProbeInvocation(resolved: ResolvedCodexExecutable, args: string[]): { command: string; args: string[] } {\n  if (process.platform !== \"win32\") {\n    return { command: resolved.executable, args };\n  }\n  if (resolved.strategy === \"cmd-shim\") {\n    const commandLine = [quoteCmdArg(resolved.executable), ...args.map(quoteCmdArg)].join(\" \");\n    return {\n      command: process.env.ComSpec || \"cmd.exe\",\n      args: [\"/d\", \"/s\", \"/c\", commandLine],\n    };\n  }\n  if (resolved.strategy === \"powershell-shim\") {\n    return {\n      command: \"powershell.exe\",\n      args: [\"-NoProfile\", \"-ExecutionPolicy\", \"Bypass\", \"-File\", resolved.executable, ...args],\n    };\n  }\n  return { command: resolved.executable, args };\n}"
      },
      "name": "buildProbeInvocation",
      "qualifiedName": "buildProbeInvocation",
      "span": {
        "end": 7430,
        "start": 6708
      }
