        "sourceSlice": "function buildReactManifest(clientManifest: ClientManifest): ReactManifest {\n  const hooks = [\n    \"ForgeProvider\",\n    \"useForgeClient\",\n    \"useAuth\",\n    \"useQuery\",\n    \"useCommand\",\n    \"useLiveQuery\",\n  ];\n\n  return {\n    schemaVersion: \"1.0.0\",\n    generatorVersion: GENERATOR_VERSION,\n    inputHash: hashStable(\n      canonicalJson({\n        clientInputHash: clientManifest.inputHash,\n        hooks,\n      }),\n    ),\n    entrypoint: \"src/forge/_generated/react.ts\",\n    hooks,\n    queries: clientManifest.queries,\n    commands: clientManifest.commands,\n    liveQueries: clientManifest.liveQueries,\n    clientSafe: true,\n  };\n}"
