      "contentHash": "58f548e1e185c6a4210fba013c1d1ad6cf18179c0a183fa49becf09a6f6fecd2",
      "file": "src/forge/compiler/dev-manifest/build.ts",
      "id": "cba1443602cc4236c456c1457a4e81a34b78a55e4ddc0c8ad2ea5aac4e6dfa30",
      "kind": "code.function",
      "meta": {
        "exportPath": "",
        "fileContentHash": "9f11d4ed45c02c421f57626ccc9fae6728f119a01439a030d0b3d79c35a81abf",
        "sourceSlice": "function buildRoutes(\n  runtimeGraph: RuntimeGraph,\n  queryRegistry: QueryRegistry,\n): DevRoute[] {\n  const routes: DevRoute[] = [\n    { method: \"GET\", path: \"/\", purpose: \"home\" },\n    { method: \"GET\", path: \"/health\", purpose: \"health\" },\n    { method: \"GET\", path: \"/entries\", purpose: \"entries\" },\n    { method: \"GET\", path: \"/queries\", purpose: \"queries\" },\n    { method: \"POST\", path: \"/ai/agents/chat\", purpose: \"ai-agent-chat\" },\n    { method: \"POST\", path: \"/ai/agents/run\", purpose: \"ai-agent-run\" },\n    { method: \"GET\", path: \"/ai/providers\", purpose: \"ai-providers\" },\n    { method: \"GET\", path: \"/workflows\", purpose: \"workflows\" },\n    { method: \"GET\", path: \"/workflows/runs\", purpose: \"workflow-runs\" },\n    { method: \"POST\", path: \"/workflows/process\", purpose: \"workflow-process\" },\n  ];\n\n  for (const query of queryRegistry.queries) {\n    routes.push({\n      method: \"POST\",\n      path: `/queries/${query.name}`,\n      purpose: \"query\",\n      entryName: query.name,\n      entryKind: \"query\",\n    });\n  }\n\n  for (const entry of runtimeGraph.entries) {\n    routes.push({\n      method: \"POST\",\n      path: `/run/${entry.name}`,\n      purpose: \"invoke\",\n      entryName: entry.name,\n      entryKind: entry.kind,\n    });\n\n    if (entry.kind === \"command\") {\n      routes.push({\n        method: \"POST\",\n        path: `/commands/${entry.name}`,\n        purpose: \"invoke\",\n        entryName: entry.name,\n        entryKind: \"command\",\n      });\n    } else {\n      routes.push({\n        method: \"POST\",\n        path: `/actions/${entry.name}`,\n        purpose: \"invoke\",\n        entryName: entry.name,\n        entryKind: \"action\",\n      });\n    }\n  }\n\n  return stableSortRoutes(routes);\n}"
      },
