        "sourceSlice": "function buildSymbols(appGraph: AppGraph | null, modules: CairModuleRef[]): CairSymbolRef[] {\n  const moduleIds = moduleIdByFile(modules);\n  return stableSortSymbols(appGraph?.symbols ?? []).map((symbol: ForgeSymbol, index) => ({\n    id: `S#${index + 1}`,\n    sourceId: symbol.id,\n    kind: symbol.kind,\n    name: symbol.name,\n    qualifiedName: symbol.qualifiedName,\n    moduleId: moduleIds.get(symbol.file) ?? null,\n    file: symbol.file,\n    span: symbol.span,\n    hash: symbol.contentHash,\n  }));\n}"
