      "file": "src/forge/compiler/test-graph/build.ts",
      "id": "fa0685240909fa4d0eb246bea5aada3560d14dfce99544768b8563ad6ad30bbd",
      "kind": "code.function",
      "meta": {
        "exportPath": "export",
        "fileContentHash": "813dafdb5995dc801be568810f9dbf1b662e9750665d7b3063dc8b3e0956e0d8",
        "sourceSlice": "function buildTestGraph(input: {\n  workspaceRoot: string;\n  inputHash: string;\n  appGraph: AppGraph;\n  packageGraph: PackageGraph;\n  sources: SourceFile[];\n}): TestGraph {\n  const diskTests = collectTestsFromDisk(input.workspaceRoot);\n  const byPath = new Map<string, SourceFile>();\n  for (const source of input.sources) {\n    if (isTestGraphCandidate(source.path)) {\n      byPath.set(source.path, source);\n    }\n  }\n  for (const source of diskTests) {\n    byPath.set(source.path, source);\n  }\n\n  const allSources = [...input.sources.filter((s) => isTestGraphCandidate(s.path)), ...diskTests];\n  const tests: TestGraphEntry[] = [...byPath.values()]\n    .sort((a, b) => a.path.localeCompare(b.path))\n    .map((source) => {\n      const kind = inferKind(source.path, source.text);\n      const inferred = inferCoverage({\n        path: source.path,\n        text: source.text,\n        appGraph: input.appGraph,\n        packageGraph: input.packageGraph,\n        allSources,\n      });\n      return {\n        file: source.path,\n        kind,\n        cost: inferCost(source.path, source.text, kind),\n        confidence: inferred.confidence,\n        covers: inferred.covers,\n        reasons: inferred.reasons,\n      };\n    });\n\n  return {\n    schemaVersion: \"0.1.0\",\n    generatorVersion: GENERATOR_VERSION,\n    analyzerVersion: \"test-graph-0.1.0\",\n    inputHash: input.inputHash,\n    tests,\n    diagnostics: [],\n  };\n}"
      },
