        "sourceSlice": "function buildVueManifest(clientManifest: ClientManifest): VueManifest {\n  const composables = [\n    \"provideForge\",\n    \"useForgeClient\",\n    \"useForgeAuth\",\n    \"useForgeQuery\",\n    \"useForgeCommand\",\n    \"useForgeLiveQuery\",\n  ];\n\n  return {\n    schemaVersion: \"1.0.0\",\n    generatorVersion: GENERATOR_VERSION,\n    inputHash: hashStable(\n      canonicalJson({\n        clientInputHash: clientManifest.inputHash,\n        composables,\n      }),\n    ),\n    entrypoint: \"src/forge/_generated/vue.ts\",\n    composables,\n    queries: clientManifest.queries,\n    commands: clientManifest.commands,\n    liveQueries: clientManifest.liveQueries,\n    clientSafe: true,\n  };\n}"
