        "sourceSlice": "function buildWorkOSAuthRegistry(\n  requiresTenant: boolean,\n): AuthRegistryArtifact {\n  return {\n    ...buildDefaultAuthRegistry(requiresTenant),\n    claims: {\n      userId: \"sub\",\n      tenantId: \"organization_id\",\n      role: \"role\",\n      roles: \"roles\",\n      permissions: \"permissions\",\n      email: \"email\",\n      name: \"name\",\n    },\n  };\n}"
