      "id": "128c48e36ec9e23a149ff4812babebec8008d8cf2f9e222325b08abc4ad4c229",
      "kind": "code.function",
      "meta": {
        "exportPath": "",
        "fileContentHash": "d29a58d494f45186c821b2b07997bda6d302c195d6720016536e70eec76de0ec",
        "sourceSlice": "function checkMkdocsTooling(workspaceRoot: string): DocsCheck {\n  const result = spawnSync(\"python3\", [\"-m\", \"mkdocs\", \"--version\"], {\n    cwd: workspaceRoot,\n    encoding: \"utf8\",\n    windowsHide: true,\n    stdio: [\"ignore\", \"pipe\", \"pipe\"],\n  });\n  if (result.status === 0) {\n    return {\n      name: \"mkdocs-tooling\",\n      ok: true,\n      status: \"pass\",\n      details: { version: (result.stdout ?? \"\").trim() },\n    };\n  }\n  return {\n    name: \"mkdocs-tooling\",\n    ok: true,\n    status: \"warning\",\n    details: {\n      message: \"mkdocs is not importable in the current Python environment; install docs/requirements.txt before building docs locally\",\n    },\n  };\n}"
      },
