        "sourceSlice": "function chunkFiles(files: string[], size: number): string[][] {\n  const chunks: string[][] = [];\n  for (let index = 0; index < files.length; index += size) {\n    chunks.push(files.slice(index, index + size));\n  }\n  return chunks;\n}"
