        "sourceSlice": "function classifyExport(\n  api: PackageApi,\n  entrypoint: string,\n  exportName: string,\n  recipe: IntegrationRecipe | undefined,\n  caps: CapabilitySet,\n  alias: string,\n  signals: PackageSignals,\n): ExportClassification {\n  const { compatible, incompatible } = partitionContexts(\n    recipe,\n    caps,\n    signals,\n    api.name,\n  );\n\n  return {\n    alias,\n    packageName: api.name,\n    entrypoint,\n    exportName,\n    compatible,\n    incompatible,\n    capabilities: caps,\n  };\n}"
