      "contentHash": "cfd3195f028cd43485c5a2fadb00afb13b51911c3e4658cb22cccd5a9fa91f07",
      "file": "src/forge/intent/index.ts",
      "id": "acbe415341ca5d401759765c7749210dd1f0e12a73bbd4073ecd11f657f7642a",
      "kind": "code.function",
      "meta": {
        "exportPath": "",
        "fileContentHash": "89967afa7b469b9d233303b572f7fcb6e04ca8ded3f5b2ea940503d13a2cf9fa",
        "sourceSlice": "function classifyIntent(tokens: string[]): { kind: ForgeIntentKind; confidence: ForgeIntentConfidence } {\n  if (tokens.length === 0) {\n    return { kind: \"inspect\", confidence: \"low\" };\n  }\n  if (includesAny(tokens, [\"fix\", \"repair\", \"corrigir\", \"consertar\", \"erro\", \"errors\", \"falha\", \"failing\"])) {\n    return { kind: \"fix\", confidence: \"high\" };\n  }\n  if (includesAny(tokens, [\"verify\", \"validar\", \"test\", \"teste\", \"tests\", \"check\", \"100\"])) {\n    return { kind: \"verify\", confidence: \"high\" };\n  }\n  if (includesAny(tokens, [\"ship\", \"handoff\", \"release\", \"commit\", \"pr\", \"push\", \"entregar\"])) {\n    return { kind: \"ship\", confidence: \"medium\" };\n  }\n  if (includesAny(tokens, [\"frontend\", \"ui\", \"route\", \"rota\", \"component\", \"page\", \"hook\", \"connect\", \"connect-ui\", \"conectar\"])) {\n    if (includesAny(tokens, [\"add\", \"add-resource\", \"create\", \"criar\", \"crie\", \"resource\", \"feature\", \"nova\", \"novo\"])) {\n      return { kind: \"add-feature\", confidence: \"high\" };\n    }\n    return { kind: \"connect-ui\", confidence: \"high\" };\n  }\n  if (includesAny(tokens, [\"add\", \"add-resource\", \"create\", \"criar\", \"crie\", \"make\", \"resource\", \"feature\", \"table\", \"command\", \"query\"])) {\n    return { kind: \"add-feature\", confidence: \"medium\" };\n  }\n  if (includesAny(tokens, [\"explain\", \"understand\", \"explicar\", \"entender\", \"describe\", \"mapa\", \"architecture\", \"arquitetura\"])) {\n    return { kind: \"explain\", confidence: \"high\" };\n  }\n  return { kind: \"inspect\", confidence: \"medium\" };\n}"
      },
      "name": "classifyIntent",
      "qualifiedName": "classifyIntent",
      "span": {
        "end": 3098,
        "start": 1624
      }
