        "sourceSlice": "function collectMatches(text: string, patterns: RegExp[]): string[] {\n  const evidence: string[] = [];\n  for (const pattern of patterns) {\n    if (pattern.test(text)) {\n      evidence.push(`pattern:${pattern.source}`);\n    }\n  }\n  return evidence;\n}"
