        "sourceSlice": "function commandArgsArray(value: unknown): value is string[] {\n  return Array.isArray(value) &&\n    value.length > 0 &&\n    typeof value[0] === \"string\" &&\n    value[0].length > 0 &&\n    value.every((item) => typeof item === \"string\");\n}"
