        "fileContentHash": "311b954064438a100833b5b3d17b53937186078cb0f65b88b975fc2c4aba0743",
        "sourceSlice": "function commandErrorToForgeError(result: Extract<ForgeCommandCallResult, { ok: false }>): ForgeReactError {\n  const error = new Error(result.error.message) as ForgeReactError;\n  error.code = result.error.code;\n  error.status = result.status;\n  error.traceId = result.traceId;\n  error.details = result.error.details ?? result.diagnostics;\n  return error;\n}"
