        "sourceSlice": "function compareSymbols(a: ForgeSymbol, b: ForgeSymbol): number {\n  let cmp = compareBytes(a.kind, b.kind);\n  if (cmp !== 0) return cmp;\n\n  cmp = compareBytes(a.name, b.name);\n  if (cmp !== 0) return cmp;\n\n  cmp = comparePaths(a.file, b.file);\n  if (cmp !== 0) return cmp;\n\n  return a.span.start - b.span.start;\n}"
