        "sourceSlice": "function contextScope(input: {\n  entry?: string;\n  change?: string;\n  proof?: string;\n  handoff?: boolean;\n}): AgentMemoryContextPack[\"scope\"] {\n  if (input.handoff) {\n    return \"handoff\";\n  }\n  if (input.proof) {\n    return \"proof\";\n  }\n  if (input.change) {\n    return \"change\";\n  }\n  return input.entry ? \"entry\" : \"current\";\n}"
