        "sourceSlice": "function corsPreflight(): Response {\n  const allowedHeaders = [\n    \"Authorization\",\n    \"Content-Type\",\n    \"WorkOS-Signature\",\n    \"x-forge-user-id\",\n    \"x-forge-tenant-id\",\n    \"x-forge-organization-id\",\n    \"x-forge-organization-membership-id\",\n    \"x-forge-role\",\n    \"x-forge-roles\",\n    \"x-forge-permissions\",\n    \"x-forge-claims\",\n    \"x-forge-auth-kind\",\n    \"x-forge-trace-id\",\n  ];\n  return new Response(null, {\n    status: 204,\n    headers: {\n      \"Access-Control-Allow-Origin\": \"*\",\n      \"Access-Control-Allow-Methods\": \"GET, POST, OPTIONS\",\n      \"Access-Control-Allow-Headers\": allowedHeaders.join(\", \"),\n    },\n  });\n}"
