        "sourceSlice": "function createActionContext(\n  db: DbClient,\n  telemetry: TelemetryContext,\n  auth: AuthContext,\n  options?: {\n    env?: Record<string, string | undefined>;\n    workspaceRoot?: string;\n    store?: RuntimeEnvStore;\n    runtimeKind?: RuntimeContext;\n    mockAi?: boolean;\n  },\n): ForgeContext {\n  const runtimeKind = options?.runtimeKind ?? \"action\";\n  const store =\n    options?.store ??\n    (options?.workspaceRoot\n      ? getRuntimeEnvStore(options.workspaceRoot)\n      : getRuntimeEnvStore());\n  const { secrets, config, ai, agent, env } = buildSecretsConfigAndAi(\n    options?.workspaceRoot,\n    runtimeKind,\n    store,\n    telemetry,\n    {\n      mockAi: options?.mockAi,\n      auth,\n      env: options?.env,\n    },\n  );\n\n  return {\n    db,\n    env: options?.env ?? env,\n    telemetry,\n    auth,\n    secrets,\n    config,\n    ai,\n    agent,\n    release: currentReleaseInfo(),\n    emit: async () => {\n      /* actions invoked by outbox worker do not emit */\n    },\n  };\n}"
