        "sourceSlice": "async function createFetchServer(\n  input: { hostname: string; port: number },\n  fetchHandler: (request: Request) => Promise<Response>,\n): Promise<FetchServer> {\n  const bunGlobal = globalThis as {\n    Bun?: {\n      serve?: (options: {\n        hostname: string;\n        port: number;\n        idleTimeout: number;\n        fetch: (request: Request) => Promise<Response>;\n      }) => FetchServer;\n    };\n  };\n\n  if (bunGlobal.Bun?.serve) {\n    return bunGlobal.Bun.serve({\n      hostname: input.hostname,\n      port: input.port,\n      idleTimeout: 255,\n      fetch: fetchHandler,\n    });\n  }\n\n  return createNodeFetchServer(input, fetchHandler);\n}"
