        "fileContentHash": "bdd6f4a72d334f30bab1f6e9a548e3f748621fabed71431d6c0b2801e543c89f",
        "sourceSlice": "function ctxSecretNamesFromText(text: string): string[] {\n  const names = new Set<string>();\n  const regex = /ctx\\.secrets\\.get\\(['\"]([A-Z0-9_]+)['\"]\\)/g;\n  let match: RegExpExecArray | null;\n  while ((match = regex.exec(text))) names.add(match[1]);\n  return [...names].sort();\n}"
