        "sourceSlice": "async function currentSessionState(store: DeltaStore, currentSession?: Awaited<ReturnType<DeltaStore[\"currentWorkSession\"]>>): Promise<Record<string, unknown>> {\n  const session = currentSession ?? await store.currentWorkSession();\n  return session\n    ? {\n        sessionId: session.id,\n        title: session.title,\n        inferredIntent: session.inferredIntent,\n        confidence: session.confidence,\n        status: session.status,\n        reasons: session.reasons.slice(0, 5).map((reason) => ({\n          signal: reason.signal,\n          weight: reason.weight,\n          ...(reason.value ? { value: reason.value } : {}),\n        })),\n      }\n    : {};\n}"
