        "sourceSlice": "function cursorInstallResult(filesWritten: string[], filesPlanned: string[]): AgentInstallResult {\n  return {\n    ok: true,\n    target: \"cursor\",\n    filesWritten,\n    filesPlanned,\n    privacy: privacyDefaults(),\n    warnings: [\"Cursor internal chats, checkpoints, and databases are not read by ForgeOS.\"],\n    exitCode: 0,\n  };\n}"
