        "sourceSlice": "function databaseUrlUsesPostgresSuperuser(databaseUrl: string | undefined): boolean {\n  if (!databaseUrl) {\n    return false;\n  }\n  try {\n    const parsed = new URL(databaseUrl);\n    return parsed.username === \"postgres\";\n  } catch {\n    return false;\n  }\n}"
