      "kind": "code.function",
      "meta": {
        "exportPath": "",
        "fileContentHash": "b1f8897c47fe81d051b0bcd1b59d0dcda927dc721a780ff8f937854d8d6f4e6d",
        "sourceSlice": "function dbTablesForFile(\n  workspaceRoot: string,\n  file: string | undefined,\n  tableLookup: Map<string, string>,\n  ops: Set<string>,\n): string[] {\n  return dbTablesForText(sourceTextWithLocalImports(workspaceRoot, file), tableLookup, ops);\n}"
      },
