        "fileContentHash": "52e87fd1320ffe308da24cb17657745d2a9300623f6df15572853271fc3ba092",
        "sourceSlice": "function decodeWorkOSDevSession(value: string | undefined, cookiePassword: string): WorkOSDevSession | null {\n  if (!value) {\n    return null;\n  }\n  const [payload, signature] = value.split(\".\");\n  if (!payload || !signature || !safeEqualString(signature, hmacBase64url(cookiePassword, payload))) {\n    return null;\n  }\n  return decodeBase64urlJson(payload) as WorkOSDevSession;\n}"
