        "sourceSlice": "function detectArtifactKind(path: string): ArtifactKind {\n  if (path.endsWith(\".json\")) {\n    return \"json\";\n  }\n  if (path.endsWith(\".ts\") || path.endsWith(\".tsx\")) {\n    return \"typescript\";\n  }\n  if (path.endsWith(\".md\")) {\n    return \"markdown\";\n  }\n  return \"text\";\n}"
