        "sourceSlice": "function detectDuplicateQueryNames(queries: QueryDefinition[]): QueryRegistry[\"diagnostics\"] {\n  const byName = new Map<string, QueryDefinition[]>();\n\n  for (const query of queries) {\n    const list = byName.get(query.name) ?? [];\n    list.push(query);\n    byName.set(query.name, list);\n  }\n\n  const diagnostics: QueryRegistry[\"diagnostics\"] = [];\n\n  for (const [name, group] of byName) {\n    if (group.length <= 1) {\n      continue;\n    }\n\n    for (const query of group) {\n      diagnostics.push(\n        createDiagnostic({\n          severity: \"warning\",\n          code: \"FORGE_DUP_QUERY\",\n          message: `duplicate query name '${name}'`,\n          file: query.file,\n        }),\n      );\n    }\n  }\n\n  return diagnostics.sort((a, b) => {\n    const fileA = a.file ?? \"\";\n    const fileB = b.file ?? \"\";\n    if (fileA !== fileB) {\n      return fileA < fileB ? -1 : 1;\n    }\n    return a.message < b.message ? -1 : a.message > b.message ? 1 : 0;\n  });\n}"
