        "fileContentHash": "f24869dfb8001db5424df29855b605e6d3653c163d2db957b7ccc3d0b1b68d2b",
        "sourceSlice": "function detectDuplicateSymbols(symbols: ForgeSymbol[]): Diagnostic[] {\n  const groups = new Map<string, ForgeSymbol[]>();\n\n  for (const symbol of symbols) {\n    const list = groups.get(symbol.id) ?? [];\n    list.push(symbol);\n    groups.set(symbol.id, list);\n  }\n\n  const diagnostics: Diagnostic[] = [];\n\n  for (const group of groups.values()) {\n    if (group.length <= 1) {\n      continue;\n    }\n    for (const symbol of group) {\n      diagnostics.push(forgeDupSymbol(symbol.qualifiedName, symbol.file));\n    }\n  }\n\n  return diagnostics;\n}"
