        "sourceSlice": "function detectDuplicateTableNames(tables: DataTable[]): DataGraph[\"diagnostics\"] {\n  const byName = new Map<string, DataTable[]>();\n\n  for (const table of tables) {\n    const list = byName.get(table.name) ?? [];\n    list.push(table);\n    byName.set(table.name, list);\n  }\n\n  const diagnostics: DataGraph[\"diagnostics\"] = [];\n\n  for (const [name, group] of byName) {\n    if (group.length <= 1) {\n      continue;\n    }\n\n    for (const table of group) {\n      diagnostics.push(\n        createDiagnostic({\n          severity: \"warning\",\n          code: \"FORGE_DUP_TABLE\",\n          message: `duplicate table name '${name}'`,\n          file: table.file,\n        }),\n      );\n    }\n  }\n\n  return diagnostics.sort((a, b) => {\n    const fileA = a.file ?? \"\";\n    const fileB = b.file ?? \"\";\n    if (fileA !== fileB) {\n      return fileA < fileB ? -1 : 1;\n    }\n    return a.message < b.message ? -1 : a.message > b.message ? 1 : 0;\n  });\n}"
