      "contentHash": "1531fe56fd9a00d36878b4a8b5b12252e6fcc73bd3d95ab21888644bf61b2b97",
      "file": "src/forge/compiler/classifier/secrets.ts",
      "id": "d1aea2c6bebf07dbf7f545075db8f04c7e83bf1d1c547872496df59321a15c7b",
      "kind": "code.function",
      "meta": {
        "exportPath": "export",
        "fileContentHash": "4099bc574530247042eead5dc2e528b44635a4b9f7828a9b24de82444de78281",
        "sourceSlice": "function detectSecrets(\n  api: PackageApi,\n  recipe?: IntegrationRecipe,\n  precomputedSignals?: PackageSignals,\n): SecretRequirement[] {\n  const found = new Map<string, SecretRequirement>();\n\n  if (recipe) {\n    for (const s of recipe.secrets) {\n      found.set(s.envVar, { ...s });\n    }\n  }\n\n  const signals = precomputedSignals ?? gatherSignals(api);\n  for (const evidence of signals.envSecretEvidence) {\n    const envVar = evidence.replace(/^env:/, \"\");\n    if (!found.has(envVar)) {\n      found.set(envVar, secret(envVar, true, \"signature\"));\n    }\n  }\n\n  for (const ep of api.entrypoints) {\n    for (const exp of ep.exports) {\n      if (!exp.jsdoc) continue;\n      for (const tag of exp.jsdoc.tags) {\n        if (tag.tag !== \"env\" && tag.tag !== \"secret\") continue;\n        const name = tag.text.trim().split(/\\s+/)[0];\n        if (name && /^[A-Z][A-Z0-9_]*$/.test(name) && !found.has(name)) {\n          found.set(name, secret(name, true, \"jsdoc\"));\n        }\n      }\n    }\n  }\n\n  return [...found.values()].sort((a, b) => a.envVar.localeCompare(b.envVar));\n}"
      },
      "name": "detectSecrets",
      "qualifiedName": "detectSecrets",
      "span": {
        "end": 1380,
        "start": 315
      }
