        "fileContentHash": "3d346f6604ed91b38ad1822e0d814524d8af5ff422cb956d435cfed3ae722760",
        "sourceSlice": "function devCommandFor(webRoot: string, framework: FrontendGraph[\"framework\"]): string {\n  const pkg = readJson<{ scripts?: Record<string, string> }>(join(webRoot, \"package.json\"));\n  if (pkg?.scripts?.dev) {\n    return \"cd web && bun run dev\";\n  }\n  if (nodeFileSystem.exists(join(webRoot, \"server.ts\"))) {\n    return \"bun web/server.ts\";\n  }\n  if (framework === \"static\") {\n    return \"forge dev --web\";\n  }\n  return \"none\";\n}"
