        "sourceSlice": "function displayDeltaBusyCwd(workspaceRoot: string, cwd: string): string {\n  if (!isAbsolute(cwd)) {\n    return cwd;\n  }\n  const rel = normalizePath(relative(workspaceRoot, cwd));\n  if (rel === \"\") {\n    return \".\";\n  }\n  if (rel === \"..\" || rel.startsWith(\"../\")) {\n    return \"[outside-workspace]\";\n  }\n  return rel;\n}"
