        "sourceSlice": "function encodeRandom(bytes: Uint8Array): string {\n  let value = BigInt(`0x${Buffer.from(bytes).toString(\"hex\")}`);\n  let output = \"\";\n  for (let index = 0; index < 16; index++) {\n    output = CROCKFORD[Number(value % 32n)] + output;\n    value = value / 32n;\n  }\n  return output;\n}"
