        "fileContentHash": "52e87fd1320ffe308da24cb17657745d2a9300623f6df15572853271fc3ba092",
        "sourceSlice": "function errorMessage(error: unknown, fallback: string): string {\n  if (error instanceof Error && error.message) {\n    return error.message;\n  }\n  if (\n    error &&\n    typeof error === \"object\" &&\n    \"message\" in error &&\n    typeof (error as { message?: unknown }).message === \"string\" &&\n    (error as { message: string }).message.length > 0\n  ) {\n    return (error as { message: string }).message;\n  }\n  if (typeof error === \"string\" && error.length > 0) {\n    return error;\n  }\n  const stringified = String(error);\n  return stringified && stringified !== \"[object Object]\" ? stringified : fallback;\n}"
