        "sourceSlice": "function eventNamesFromText(text: string): string[] {\n  const events = new Set<string>();\n  const regex = /ctx\\.emit\\s*\\(\\s*[\"'`]([^\"'`]+)[\"'`]/g;\n  let match: RegExpExecArray | null;\n  while ((match = regex.exec(text))) events.add(match[1]);\n  return [...events].sort();\n}"
