        "sourceSlice": "function eventTarget(\n  input: { entry?: string; change?: string; proof?: string },\n  scope: AgentMemoryContextPack[\"scope\"],\n): string | undefined {\n  if (scope === \"entry\") {\n    return input.entry;\n  }\n  if (scope === \"proof\") {\n    return input.proof;\n  }\n  if (scope === \"change\" && input.change !== \"current\") {\n    return input.change;\n  }\n  return undefined;\n}"
