      "contentHash": "37a75544e67c28e86758d7b335d3a902144d46501d3e65a6ec8adf57e0f63048",
      "file": "src/forge/runtime/runner/run-entry.ts",
      "id": "678c31e15141bfb3a5e965e28a5d186055cf3066009c72ad43b647634dc89eb3",
      "kind": "code.function",
      "meta": {
        "exportPath": "export",
        "fileContentHash": "4298cb4334cf8a46afa8da07ca310e0ddf82013adf4ac0532358ab7845b62b60",
        "sourceSlice": "async function executeResolvedEntry(\n  workspaceRoot: string,\n  entry: RuntimeEntry,\n  resolved: ResolvedHandler,\n  options: RunEntryExecutionOptions,\n  runtime?: RunEntryRuntime,\n): Promise<{\n  ok: boolean;\n  result?: unknown;\n  diagnostics: Diagnostic[];\n}> {\n  const diagnostics: Diagnostic[] = [];\n\n  if (\n    entry.kind === \"command\" &&\n    resolved.usesContext &&\n    runtime?.adapter &&\n    runtime.tableMap\n  ) {\n    const handler = resolved.handler;\n    if (!handler) {\n      return {\n        ok: false,\n        diagnostics: [\n          createDiagnostic({\n            severity: \"error\",\n            code: FORGE_RUNTIME_NOT_FOUND,\n            message: `runtime entry '${entry.name}' is missing a command handler`,\n            file: entry.file,\n          }),\n        ],\n      };\n    }\n\n    return runCommandWithTransaction(\n      entry,\n      handler,\n      options.args ?? {},\n      {\n        adapter: runtime.adapter,\n        tableMap: runtime.tableMap,\n        workspaceRoot,\n        requestId: runtime.requestId,\n        auth: options.auth ?? runtime.auth,\n        liveManager: runtime.liveManager,\n      },\n    );\n  }\n\n  try {\n    const result = await resolved.invoke(options.args ?? {});\n    return { ok: true, result, diagnostics };\n  } catch (error) {\n    const message = error instanceof Error ? error.message : \"handler execution failed\";\n    const dbHint = needsDatabaseHint(entry, resolved, runtime);\n    diagnostics.push(\n      createDiagnostic({\n        severity: \"error\",\n        code: dbHint ? FORGE_DB_ADAPTER_UNAVAILABLE : FORGE_RUNTIME_NOT_FOUND,\n        message: dbHint\n          ? `runtime entry '${entry.name}' needs a database adapter: ${message}`\n          : `runtime entry '${entry.name}' failed: ${message}`,\n        file: entry.file,\n        fixHint: dbHint\n          ? \"Start `forge dev` and invoke the HTTP endpoint, or run database-backed entries from a DB-enabled workflow/test.\"\n          : undefined,\n        suggestedCommands: dbHint\n          ? [\"forge dev\", \"forge dev --once --json\"]\n          : undefined,\n      }),\n    );\n    return { ok: false, diagnostics };\n  }\n}"
      },
      "name": "executeResolvedEntry",
      "qualifiedName": "executeResolvedEntry",
      "span": {
        "end": 7112,
        "start": 5000
      }
