        "fileContentHash": "243b434911e3d45c92594038797092832fdfddb15a6fb9a15953193a4dd6bad6",
        "sourceSlice": "function extractEntriesFromCommand(command: string | undefined): string[] {\n  if (!command) {\n    return [];\n  }\n  const entries: string[] = [];\n  const forgeEntryPattern = /\\b(?:run|query|explain|timeline)\\s+([a-zA-Z0-9_.:-]+)/g;\n  for (const match of command.matchAll(forgeEntryPattern)) {\n    const value = match[1];\n    if (value && value.includes(\".\")) {\n      entries.push(value);\n    }\n  }\n  return entries;\n}"
