        "sourceSlice": "function extractNamedValues(value: unknown, keys: string[]): string[] {\n  const wanted = new Set(keys);\n  const values: string[] = [];\n  visit(value, (key, child) => {\n    if (wanted.has(key) && typeof child === \"string\" && child.length > 0) {\n      values.push(child);\n    }\n  });\n  return values;\n}"
