      "meta": {
        "exportPath": "",
        "fileContentHash": "1107f859cd1bca753b5814fd6af1728d31ed38241a39da57bb540515e390fcbc",
        "sourceSlice": "function failureKind(errors: Diagnostic[]): string | undefined {\n  if (errors.length === 0) {\n    return undefined;\n  }\n  const first = errors[0];\n  if (first?.code === \"FORGE_UNKNOWN_ALIAS\") {\n    return \"unknown_alias\";\n  }\n  if (first?.code === \"FORGE_ADD_INSTALL_FAILED\") {\n    return \"install_failed\";\n  }\n  if (errors.some((error) => error.code === \"FORGE_WRITE_ERROR\")) {\n    return \"write_failed\";\n  }\n  if (errors.some((error) => error.code === \"FORGE_LOCK_INTEGRITY\")) {\n    return \"lock_integrity\";\n  }\n  return \"error\";\n}"
      },
