        "sourceSlice": "function forbiddenLeakLike(text: string): boolean {\n  return /sk-[a-z0-9_-]{8,}|api[_ -]?key\\s*[:=]|secret\\s+(value|is)|tenant-b-private|deleted ticket|refund(ed)? without approval/i.test(text);\n}"
