      "id": "66a6f5f3ea5313fe7b05edc93793e2258f2035ef1daaa2a53e8edbf578219273",
      "kind": "code.function",
      "meta": {
        "exportPath": "export",
        "fileContentHash": "20f8ff1edbc785f694c5b92439aa7ab0c1dd6a33cc3d476729a65b6ed8d1ad3e",
        "sourceSlice": "function formatBaselineHuman(result: BaselineCommandResult): string {\n  const label = result.required ? \"missing\" : result.summary.tracking === \"git\" ? \"not required (git workspace)\" : \"ready\";\n  const lines = [\n    `Forge baseline: ${label}`,\n    `Path: ${result.path}`,\n    `Tracking: ${result.summary.tracking}`,\n    `Files: ${result.summary.files}`,\n  ];\n  if (result.summary.reason) {\n    lines.push(`Reason: ${result.summary.reason}`);\n  }\n  lines.push(\"\", \"Next:\", ...result.nextActions.map((action) => `  ${action}`));\n  return `${lines.join(\"\\n\")}\\n`;\n}"
      },
