      "meta": {
        "exportPath": "export",
        "fileContentHash": "50f21501658975eda61b01ed85aa24ec25c46eafc70de7236f30a08e635cabfe",
        "sourceSlice": "function formatDbHuman(subcommand: DbSubcommand, result: DbCommandResult): string {\n  if (!result.ok) {\n    return result.diagnostics\n      .map((diagnostic) => `error ${diagnostic.code}: ${diagnostic.message}`)\n      .join(\"\\n\")\n      .concat(\"\\n\");\n  }\n\n  if (subcommand === \"migrate\") {\n    return `migrated ${(result.data as { migrationId: string }).migrationId}\\n`;\n  }\n\n  if (subcommand === \"reset\") {\n    return \"database reset complete\\n\";\n  }\n\n  if (subcommand === \"status\" || subcommand === \"diff\" || subcommand === \"doctor\" || subcommand === \"repair\") {\n    return `${JSON.stringify(result.data, null, 2)}\\n`;\n  }\n\n  return \"\";\n}"
      },
      "name": "formatDbHuman",
      "qualifiedName": "formatDbHuman",
