      "id": "39f6befc975e5ff4819fd2506fe531556b137ffe3da9b5c841ff7588f2466123",
      "kind": "code.function",
      "meta": {
        "exportPath": "export",
        "fileContentHash": "4aedc132dff17baa094d778d2c261a24a9db410d6ab4d8f25813a21780cd5102",
        "sourceSlice": "function formatDeltaRepairHuman(result: DeltaRepairResult): string {\n  const lines = [\n    `Forge Delta repair ${result.ok ? (result.applied ? \"applied\" : \"planned\") : \"failed\"}`,\n    \"\",\n    `Store: ${result.store}`,\n  ];\n  if (result.backupPath) {\n    lines.push(`Backup: ${result.backupPath}`);\n  }\n  lines.push(\"\", \"Actions:\");\n  for (const action of result.actions) {\n    lines.push(`  ${action.kind}${action.from ? ` ${action.from}` : \"\"}${action.to ? ` -> ${action.to}` : \"\"}${action.skipped ? \" (skipped)\" : \"\"}`);\n  }\n  if (result.diagnostics.length > 0) {\n    lines.push(\"\", \"Diagnostics:\");\n    for (const diagnostic of result.diagnostics) {\n      lines.push(`  ${diagnostic.code}: ${diagnostic.message}`);\n    }\n  }\n  if (result.nextActions.length > 0) {\n    lines.push(\"\", \"Next:\");\n    for (const action of result.nextActions) {\n      lines.push(`  ${action}`);\n    }\n  }\n  return `${lines.join(\"\\n\")}\\n`;\n}"
      },
