      "id": "31e7b0859efc320cf20070e493d25656074c40aea9ca9dd32c1044957e3b40d2",
      "kind": "code.function",
      "meta": {
        "exportPath": "export",
        "fileContentHash": "209a343af684e5246f30984d960d9b07b0f01d7afc443d93f293e2a9edfdb735",
        "sourceSlice": "function formatDeltaSessionHuman(result: DeltaSessionCommandResult): string {\n  if (!result.ok) {\n    return `${result.message ?? \"session command failed\"}\\n`;\n  }\n  if (result.sessions) {\n    const lines = [\"Work Sessions\", \"\"];\n    if (result.sessions.length === 0) {\n      lines.push(\"none\");\n    } else {\n      for (const session of result.sessions) {\n        lines.push(`${session.id} ${session.status} ${session.confidence.toFixed(2)} ${session.title}`);\n      }\n    }\n    return `${lines.join(\"\\n\")}\\n`;\n  }\n  if (result.session) {\n    return formatWorkSessionDetails(result.session);\n  }\n  if (result.detached !== undefined) {\n    return result.detached ? \"operation detached\\n\" : \"operation was not linked\\n\";\n  }\n  return \"session ok\\n\";\n}"
      },
