      "contentHash": "4cc98612c2749fd5c981c580797ee54ce024c30291b7f503138b46a3373dfbea",
      "file": "src/forge/cli/refactor.ts",
      "id": "e5d28090bfec31a5da8a12bf38958d2a218ff4bbdf2d5c4bafb732dc8cedf587",
      "kind": "code.function",
      "meta": {
        "exportPath": "export",
        "fileContentHash": "d9fe67632119d77896c08860a0b5f0bba85ed433f44386f7bcc561544a11b683",
        "sourceSlice": "function formatRefactorHuman(result: RefactorResult): string {\n  if (result.diff) {\n    return result.diff;\n  }\n  if (result.records) {\n    return `Refactors:\\n${result.records.map((record) => `- ${record.id} ${record.status}`).join(\"\\n\") || \"- none\"}\\n`;\n  }\n  if (!result.plan) {\n    return `Refactor ${result.ok ? \"ok\" : \"failed\"}\\n${result.explanation ?? \"\"}${formatDiagnostics(result.diagnostics)}`;\n  }\n  const lines = [\n    `Refactor plan: ${result.plan.id}`,\n    \"\",\n    result.plan.summary,\n    \"\",\n    `Risk: ${result.plan.risk.level}`,\n    \"\",\n    \"Will modify:\",\n    ...(result.plan.filesToModify.length > 0\n      ? result.plan.filesToModify.map((patch) => `- ${patch.file}`)\n      : [\"- none\"]),\n    \"\",\n    \"Will create:\",\n    ...(result.plan.filesToCreate.length > 0\n      ? result.plan.filesToCreate.map((file) => `- ${file.file}`)\n      : [\"- none\"]),\n  ];\n  if (result.plan.migrationPlan) {\n    lines.push(\"\", \"Migration hint:\", ...result.plan.migrationPlan.sql.map((sql) => `- ${sql}`));\n  }\n  if (result.explanation) {\n    lines.push(\"\", result.explanation);\n  }\n  return `${lines.join(\"\\n\")}\\n${formatDiagnostics(result.diagnostics)}`;\n}"
      },
      "name": "formatRefactorHuman",
      "qualifiedName": "formatRefactorHuman",
      "span": {
        "end": 6925,
        "start": 5767
      }
