      "contentHash": "5e7047c61626ad62df7cf3199c5f9447be56e282ec820ca9891033f351439d3a",
      "file": "src/forge/cli/telemetry.ts",
      "id": "fc65779f5be75a463e65340398a53f57c1094dfa7e8241a6e0208a315a2b9dfa",
      "kind": "code.function",
      "meta": {
        "exportPath": "export",
        "fileContentHash": "eed76f1aba65b899d9765c5effbc2282203d6e064b15a4af048bd26e30a5806c",
        "sourceSlice": "function formatTelemetryHuman(\n  subcommand: TelemetrySubcommand,\n  result: TelemetryCommandResult,\n): string {\n  if (!result.ok) {\n    return result.diagnostics\n      .map((diagnostic) => `error ${diagnostic.code}: ${diagnostic.message}`)\n      .join(\"\\n\")\n      .concat(\"\\n\");\n  }\n\n  if (subcommand === \"flush\") {\n    const batch = result.data as { processed: number; failed: number };\n    return `processed=${batch.processed} failed=${batch.failed}\\n`;\n  }\n\n  if (subcommand === \"clear\") {\n    return `cleared ${(result.data as { cleared: number }).cleared} telemetry rows\\n`;\n  }\n\n  if (subcommand === \"tail\") {\n    const tail = result.data as { file: string; lines: string[] };\n    return tail.lines.join(\"\\n\").concat(\"\\n\");\n  }\n\n  return `${JSON.stringify(result.data, null, 2)}\\n`;\n}"
      },
      "name": "formatTelemetryHuman",
      "qualifiedName": "formatTelemetryHuman",
      "span": {
        "end": 6195,
        "start": 5405
      }
