        "sourceSlice": "function inputType(fields: MakeFieldSpec[]): string {\n  const entries = inputFields(fields);\n  if (entries.length === 0) {\n    return \"Record<string, never>\";\n  }\n  return `{ ${entries.map((field) => `${field.name}${field.optional ? \"?\" : \"\"}: ${typeForTs(field)}`).join(\"; \")} }`;\n}"
