        "sourceSlice": "async function isPortAvailable(host: string, port: number): Promise<boolean> {\n  if (port === 0) {\n    return true;\n  }\n  const server = createNetServer();\n  return new Promise<boolean>((resolve) => {\n    const cleanup = () => {\n      server.removeAllListeners();\n    };\n    server.once(\"error\", () => {\n      cleanup();\n      resolve(false);\n    });\n    server.listen(port, host, () => {\n      server.close(() => {\n        cleanup();\n        resolve(true);\n      });\n    });\n  });\n}"
