      "meta": {
        "exportPath": "",
        "fileContentHash": "f64fef00db0ce682d123cef03b225189763366e2f879f66dbe843e350064c22c",
        "sourceSlice": "function listScopeFiles(workspaceRoot: string, scope: string): string[] {\n  const resolved = resolveRepoPath(workspaceRoot, scope.replace(/\\*\\*.*$/, \"\"), true);\n  const root = resolved.path?.absolutePath ?? workspaceRoot;\n  const files: string[] = [];\n  function visit(path: string): void {\n    if (!existsSync(path)) {\n      return;\n    }\n    const stat = statSync(path);\n    if (stat.isFile()) {\n      const repoPath = normalizeSlashes(relative(workspaceRoot, path));\n      if (shouldScanFile(repoPath)) {\n        files.push(path);\n      }\n      return;\n    }\n    if (!stat.isDirectory()) {\n      return;\n    }\n    const repoPath = normalizeSlashes(relative(workspaceRoot, path));\n    if (repoPath.includes(\"node_modules\") || repoPath.includes(\"_generated\")) {\n      return;\n    }\n    for (const entry of readdirSync(path)) {\n      visit(join(path, entry));\n    }\n  }\n  visit(root);\n  return files.sort();\n}"
      },
