      "contentHash": "fb17656ecce1d0d92237ef79505bfc904753212c71a2f5cf9e348f7a189fd192",
      "file": "src/forge/dev-console/cycle.ts",
      "id": "0e159ae80c807332c9a61c100c3d26eec320f7c5b9c239467a43b9bd91ee320c",
      "kind": "code.function",
      "meta": {
        "exportPath": "",
        "fileContentHash": "aeade6163f7acf6db36e88c9f2adeb5ba6dab9def290acdaee76fe72a4b2c441",
        "sourceSlice": "function nextActionsFromPhases(workspaceRoot: string, phases: DevConsolePhase[]): DevConsoleNextAction[] {\n  const actions: DevConsoleNextAction[] = [];\n  const diagnostics = phases.flatMap((item) => item.diagnostics);\n  if (diagnostics.some((diagnostic) => diagnostic.severity === \"error\")) {\n    actions.push({\n      command: \"forge do fix --json\",\n      reason: \"centralize the repair path before choosing lower-level commands\",\n      confidence: \"high\",\n    });\n  }\n  if (diagnostics.some((diagnostic) => diagnostic.code.startsWith(\"FORGE_FRONTEND_\"))) {\n    actions.push({\n      command: \"forge do connect-ui --json\",\n      reason: \"frontend diagnostics are present; inspect bridge/routes/hooks as one workflow\",\n      confidence: \"high\",\n    });\n  }\n  const generated = phases.find((item) => item.name === \"generated\");\n  if (generated && !generated.ok) {\n    const generatedHasErrors = generated.diagnostics.some((diagnostic) => diagnostic.severity === \"error\");\n    if (generatedHasErrors) {\n      actions.push({\n        command: \"forge do fix --json\",\n        reason: \"generated artifacts could not be checked; use the guided repair path before lower-level commands\",\n        confidence: \"high\",\n      });\n    }\n    actions.push({\n      command: \"forge generate\",\n      reason: generatedHasErrors ? \"regenerate artifacts after guided repair\" : \"generated artifacts are stale\",\n      confidence: \"high\",\n    });\n    actions.push({\n      command: \"forge generate --check\",\n      reason: \"confirm generated artifacts are fresh after regeneration\",\n      confidence: \"high\",\n    });\n  }\n\n  for (const diagnostic of phases.flatMap((item) => item.diagnostics)) {\n    for (const command of diagnostic.suggestedCommands ?? []) {\n      actions.push({\n        command,\n        reason: `${diagnostic.code}: ${diagnostic.fixHint ?? diagnostic.message}`,\n        confidence: diagnostic.severity === \"error\" ? \"high\" : \"medium\",\n      });\n    }\n  }\n\n  const impact = phases.find((item) => item.name === \"impact\");\n  const summary = impact?.details?.summary as ImpactSummary | undefined;\n  if (summary && summary.changedFiles > 0) {\n    actions.push({\n      command: \"forge changed --json\",\n      reason: \"changed files were detected; inspect grouped human and generated changes first\",\n      confidence: \"high\",\n    });\n    actions.push({\n      command: \"forge do verify --json\",\n      reason: \"changed files were detected; use the guided verification path\",\n      confidence: \"high\",\n    });\n    actions.push({\n      command: \"forge test plan --changed --json\",\n      reason: \"changed files were detected; plan targeted checks\",\n      confidence: \"high\",\n    });\n    actions.push({\n      command: \"forge verify --changed\",\n      reason: \"run the focused verification gate for changed files\",\n      confidence: \"medium\",\n    });\n  }\n\n  if (actions.length === 0) {\n    actions.push({\n      command: \"forge dev\",\n      reason: \"project diagnostics are clean; keep the dev console watching for changes\",\n      confidence: \"medium\",\n    });\n  }\n\n  return uniqueActions(actions).slice(0, 12).map((action) => ({\n    ...action,\n    command: forgeCliCommandForWorkspace(workspaceRoot, action.command),\n  }));\n}"
      },
      "name": "nextActionsFromPhases",
      "qualifiedName": "nextActionsFromPhases",
      "span": {
        "end": 26867,
        "start": 23670
      }
