        "sourceSlice": "function normalizeForgeCommand(command: string): string {\n  return command\n    .trim()\n    .replace(/^node\\s+(?:\\.\\/)?bin\\/forge\\.mjs(?:\\s+|$)/u, \"\")\n    .replace(/^bun\\s+run\\s+forge(?:\\s+|$)/u, \"\")\n    .replace(/^npm\\s+run\\s+forge\\s+--(?:\\s+|$)/u, \"\")\n    .replace(/^forge(?:\\s+|$)/u, \"\")\n    .replace(/\\s+/gu, \" \")\n    .trim();\n}"
