        "sourceSlice": "function normalizeQueryVerb(value: string | undefined): string | undefined {\n  const upper = value?.toUpperCase();\n  switch (upper) {\n    case \"ST\":\n      return \"STATUS\";\n    case \"C\":\n      return \"CHANGED\";\n    case \"S\":\n      return \"SYMBOL\";\n    case \"D\":\n      return \"DEF\";\n    case \"R\":\n      return \"REFS\";\n    case \"I\":\n      return \"IMPACT\";\n    case \"M\":\n      return \"MODULE\";\n    case \"T\":\n      return \"TESTS\";\n    case \"API\":\n      return \"DEP.API\";\n    case \"H\":\n      return \"HELP\";\n    default:\n      return upper;\n  }\n}"
