        "fileContentHash": "a95522640f9cfd69562a3dbfdd400f3e55da04200ea76b1c4035b844007fe017",
        "sourceSlice": "function objectLiteralHasStringProperty(node: ts.ObjectLiteralExpression, key: string, value: string): boolean {\n  return node.properties.some((property) => {\n    if (!ts.isPropertyAssignment(property)) {\n      return false;\n    }\n    if (!ts.isIdentifier(property.name) && !ts.isStringLiteral(property.name)) {\n      return false;\n    }\n    if (property.name.text !== key) {\n      return false;\n    }\n    return ts.isStringLiteralLike(property.initializer) && property.initializer.text === value;\n  });\n}"
