        "sourceSlice": "function openBrowser(url: string): void {\n  const platform = process.platform;\n  const command =\n    platform === \"win32\"\n      ? [\"cmd\", \"/c\", \"start\", \"\", url]\n      : platform === \"darwin\"\n        ? [\"open\", url]\n        : [\"xdg-open\", url];\n  try {\n    const child = spawn(command[0]!, command.slice(1), {\n      stdio: \"ignore\",\n      detached: true,\n      windowsHide: true,\n    });\n    child.unref();\n  } catch {\n    // Opening a browser is best-effort; dev server startup should not fail.\n  }\n}"
