      "meta": {
        "exportPath": "",
        "fileContentHash": "7fe8422f001524f021168c69bc8ea96aeaac26e66098d188414c375fc04636d7",
        "sourceSlice": "function parseClaims(value: string | null): Record<string, unknown> | undefined {\n  if (!value) {\n    return undefined;\n  }\n  try {\n    const parsed = JSON.parse(value) as unknown;\n    if (parsed && typeof parsed === \"object\" && !Array.isArray(parsed)) {\n      return parsed as Record<string, unknown>;\n    }\n  } catch {\n    // Invalid dev claims should not break the whole request; policies can still use explicit headers.\n  }\n  return undefined;\n}"
      },
