      "meta": {
        "exportPath": "export",
        "fileContentHash": "e3174f08a0773553a99cff1fdef85f4d05fdc6d331bf4a72550ada50812c7e6c",
        "sourceSlice": "function parseExternalCommandLineDetailed(command: string): ExternalCommandLineParseResult {\n  const parts: string[] = [];\n  let current = \"\";\n  let quote: \"'\" | \"\\\"\" | null = null;\n  let escaping = false;\n  let tokenStarted = false;\n  const diagnostics: string[] = [];\n\n  const push = () => {\n    if (tokenStarted || current.length > 0) {\n      parts.push(current);\n      current = \"\";\n      tokenStarted = false;\n    }\n  };\n\n  for (const char of command) {\n    if (escaping) {\n      current += char;\n      tokenStarted = true;\n      escaping = false;\n      continue;\n    }\n    if (quote === \"'\") {\n      if (char === \"'\") {\n        quote = null;\n      } else {\n        current += char;\n        tokenStarted = true;\n      }\n      continue;\n    }\n    if (quote === \"\\\"\") {\n      if (char === \"\\\"\") {\n        quote = null;\n      } else if (char === \"\\\\\") {\n        escaping = true;\n      } else {\n        current += char;\n        tokenStarted = true;\n      }\n      continue;\n    }\n    if (char === \"\\\\\") {\n      escaping = true;\n      continue;\n    }\n    if (char === \"'\" || char === \"\\\"\") {\n      quote = char;\n      tokenStarted = true;\n      continue;\n    }\n    if (/\\s/.test(char)) {\n      push();\n      continue;\n    }\n    current += char;\n    tokenStarted = true;\n  }\n  if (escaping) {\n    current += \"\\\\\";\n    tokenStarted = true;\n    diagnostics.push(\"stdio command ends with a trailing escape\");\n  }\n  if (quote) {\n    diagnostics.push(`stdio command has an unterminated ${quote === \"'\" ? \"single\" : \"double\"} quote`);\n  }\n  push();\n  return { args: parts, diagnostics };\n}"
      },
