      "id": "f0028124f118df616ad4c7fc1aa42c3ac44278eda6bc615840612475a0b6f555",
      "kind": "code.function",
      "meta": {
        "exportPath": "",
        "fileContentHash": "e3b174357ec89d61daecf9da91247f83f830e2170842036494f2666ab17734e8",
        "sourceSlice": "function parseFieldOptions(options: MakeCommandOptions): {\n  fields: MakeFieldSpec[];\n  field?: MakeFieldSpec;\n  diagnostics: Diagnostic[];\n} {\n  const fieldSpecs = options.fieldSpecs.map((fieldSpec) =>\n    options.values && /^[a-zA-Z][a-zA-Z0-9_]*:enum(?::|$)/.test(fieldSpec)\n      ? fieldSpec.replace(\":enum\", `:enum(${options.values})`)\n      : fieldSpec,\n  );\n  const rawFields = [\n    ...(options.fieldsRaw ? [options.fieldsRaw] : []),\n    ...fieldSpecs,\n  ];\n  const parsed = parseFields(rawFields);\n  const diagnostics = [...parsed.diagnostics];\n\n  if (options.primitive === \"field\") {\n    const name = options.name?.includes(\".\")\n      ? options.name.split(\".\").pop()\n      : options.name;\n    const type = options.type ?? \"text\";\n    const rawType =\n      type === \"enum\"\n        ? `enum(${options.values ?? \"open,closed\"})`\n        : type === \"ref\"\n          ? `ref(${options.table ?? \"\"})`\n          : type;\n    const raw = [\n      `${name ?? \"field\"}:${rawType}`,\n      options.index ? \"index\" : \"\",\n      options.defaultValue ? `default=${options.defaultValue}` : \"\",\n    ]\n      .filter(Boolean)\n      .join(\":\");\n    const field = parseFieldSpec(raw);\n    diagnostics.push(...field.diagnostics);\n    return { fields: parsed.fields, field: field.field, diagnostics };\n  }\n\n  return { fields: parsed.fields, diagnostics };\n}"
      },
