        "sourceSlice": "function parseHunkStart(header: string, marker: \"-\" | \"+\"): number {\n  const pattern = marker === \"-\"\n    ? /^@@ -(\\d+)(?:,\\d+)? \\+\\d+(?:,\\d+)? @@/\n    : /^@@ -\\d+(?:,\\d+)? \\+(\\d+)(?:,\\d+)? @@/;\n  const match = header.match(pattern);\n  return match ? Number(match[1]) : 1;\n}"
