        "sourceSlice": "function parseMappings(map: SourceMapV3): Mapping[] {\n  const mappings: Mapping[] = [];\n  let sourceIndex = 0;\n  let originalLine = 0;\n  let originalColumn = 0;\n  let nameIndex = 0;\n\n  const lines = map.mappings.split(\";\");\n  for (let lineIndex = 0; lineIndex < lines.length; lineIndex++) {\n    let generatedColumn = 0;\n    const segments = lines[lineIndex]?.split(\",\").filter(Boolean) ?? [];\n    for (const segment of segments) {\n      const values = decodeVlq(segment);\n      if (values.length < 4) {\n        continue;\n      }\n      generatedColumn += values[0] ?? 0;\n      sourceIndex += values[1] ?? 0;\n      originalLine += values[2] ?? 0;\n      originalColumn += values[3] ?? 0;\n      if (values.length >= 5) {\n        nameIndex += values[4] ?? 0;\n      }\n      mappings.push({\n        generatedLine: lineIndex + 1,\n        generatedColumn,\n        sourceIndex,\n        originalLine: originalLine + 1,\n        originalColumn,\n        ...(values.length >= 5 ? { nameIndex } : {}),\n      });\n    }\n  }\n  return mappings;\n}"
