        "sourceSlice": "function parseObjectToolKeys(raw: string | undefined): string[] {\n  if (!raw) return [];\n  const explicit = [...raw.matchAll(/([A-Za-z_$][A-Za-z0-9_$]*)\\s*:/g)]\n    .map((match) => match[1] ?? \"\")\n    .filter(Boolean);\n  const shorthand = raw\n    .split(\",\")\n    .map((part) => part.trim())\n    .filter((part) => /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(part));\n  return [...new Set([...explicit, ...shorthand])].sort();\n}"
