        "sourceSlice": "function parsePoliciesFromSlice(sourceSlice: string): Array<{\n  name: string;\n  kind: \"roles\" | \"permissions\" | \"public\" | \"system\";\n  roles: string[];\n  permissions: string[];\n}> {\n  const policies: Array<{\n    name: string;\n    kind: \"roles\" | \"permissions\" | \"public\" | \"system\";\n    roles: string[];\n    permissions: string[];\n  }> = [];\n\n  for (const match of sourceSlice.matchAll(POLICY_ROLE_PATTERN)) {\n    const name = match[1];\n    const rolesArg = match[2] ?? \"\";\n    if (!name) {\n      continue;\n    }\n    policies.push({\n      name,\n      kind: \"roles\",\n      roles: parseRolesFromCanRoleArg(rolesArg),\n      permissions: [],\n    });\n  }\n\n  for (const match of sourceSlice.matchAll(POLICY_PERMISSION_PATTERN)) {\n    const name = match[1];\n    const permissionsArg = match[2] ?? \"\";\n    if (!name) {\n      continue;\n    }\n    policies.push({\n      name,\n      kind: \"permissions\",\n      roles: [],\n      permissions: parseStringsFromArg(permissionsArg),\n    });\n  }\n\n  return policies;\n}"
