        "sourceSlice": "function parseSqlLiteral(token: string, params: unknown[]): unknown {\n  const paramMatch = token.match(/^\\$(\\d+)/);\n  if (paramMatch?.[1]) {\n    return params[Number(paramMatch[1]) - 1];\n  }\n  if (/^now\\(\\)$/i.test(token)) {\n    return parseNow();\n  }\n  if (/^null$/i.test(token)) {\n    return null;\n  }\n  if (\n    (token.startsWith(\"'\") && token.endsWith(\"'\")) ||\n    (token.startsWith(\"\\\"\") && token.endsWith(\"\\\"\"))\n  ) {\n    return token.slice(1, -1);\n  }\n  const numeric = Number(token);\n  return Number.isFinite(numeric) ? numeric : token;\n}"
