        "sourceSlice": "function parseTimestampedSignatureHeader(header: string): { timestampRaw?: string; timestamp?: number; signatures: string[] } {\n  const signatures: string[] = [];\n  let timestampRaw: string | undefined;\n  let timestamp: number | undefined;\n  for (const part of header.split(\",\")) {\n    const [key, value] = part.split(\"=\", 2).map((item) => item.trim());\n    if (key === \"t\") {\n      timestampRaw = value;\n      const parsed = Number(value);\n      if (Number.isFinite(parsed)) {\n        timestamp = parsed;\n      }\n    }\n    if (key === \"v1\" && value) {\n      signatures.push(value);\n    }\n  }\n  return { timestampRaw, timestamp, signatures };\n}"
