        "sourceSlice": "function processIsRunning(pid: number | undefined): boolean {\n  if (!pid || !Number.isInteger(pid) || pid <= 0) {\n    return false;\n  }\n  try {\n    process.kill(pid, 0);\n    return true;\n  } catch {\n    return false;\n  }\n}"
