        "fileContentHash": "bdd6f4a72d334f30bab1f6e9a548e3f748621fabed71431d6c0b2801e543c89f",
        "sourceSlice": "function publicSecretNamesFromText(text: string): string[] {\n  const names = new Set<string>();\n  for (const regex of [/process\\.env\\.([A-Z0-9_]+)/g, /process\\.env\\[['\"]([A-Z0-9_]+)['\"]\\]/g]) {\n    let match: RegExpExecArray | null;\n    while ((match = regex.exec(text))) {\n      const name = match[1];\n      if ((name.startsWith(\"PUBLIC_\") || name.startsWith(\"NEXT_PUBLIC_\")) && isSecretEnvName(name)) {\n        names.add(name);\n      }\n    }\n  }\n  return [...names].sort();\n}"
