        "sourceSlice": "function quotedArrayProperty(block: string, name: string): string[] {\n  const match = new RegExp(`\\\\b${name}\\\\s*:\\\\s*\\\\[([\\\\s\\\\S]*?)\\\\]`).exec(block);\n  if (!match) return [];\n  return [...match[1]!.matchAll(/[\"']([^\"']+)[\"']/g)].map((item) => item[1]!).filter(Boolean);\n}"
