      "meta": {
        "exportPath": "",
        "fileContentHash": "60f466f896416928a85e8ebc7ebd09e5189c57630c633a764564dd279efb58f3",
        "sourceSlice": "function quotedOrCommentRanges(source: string): Array<{ start: number; end: number }> {\n  const ranges: Array<{ start: number; end: number }> = [];\n  let i = 0;\n\n  while (i < source.length) {\n    const char = source[i];\n    const next = source[i + 1];\n\n    if (char === \"/\" && next === \"/\") {\n      const start = i;\n      i += 2;\n      while (i < source.length && source[i] !== \"\\n\") {\n        i += 1;\n      }\n      ranges.push({ start, end: i });\n      continue;\n    }\n\n    if (char === \"/\" && next === \"*\") {\n      const start = i;\n      i += 2;\n      while (i < source.length && !(source[i] === \"*\" && source[i + 1] === \"/\")) {\n        i += 1;\n      }\n      i = Math.min(source.length, i + 2);\n      ranges.push({ start, end: i });\n      continue;\n    }\n\n    if (char === \"\\\"\" || char === \"'\" || char === \"`\") {\n      const quote = char;\n      const start = i;\n      i += 1;\n      while (i < source.length) {\n        if (source[i] === \"\\\\\") {\n          i += 2;\n          continue;\n        }\n        if (source[i] === quote) {\n          i += 1;\n          break;\n        }\n        i += 1;\n      }\n      ranges.push({ start, end: i });\n      continue;\n    }\n\n    i += 1;\n  }\n\n  return ranges;\n}"
      },
      "name": "quotedOrCommentRanges",
      "qualifiedName": "quotedOrCommentRanges",
      "span": {
        "end": 1764,
        "start": 570
      }
