        "sourceSlice": "function readFeaturePlan(workspaceRoot: string, featureIdOrPath: string): FeaturePlan | null {\n  const candidates = [\n    featureIdOrPath,\n    `${FEATURE_PLAN_DIR}/${featureIdOrPath}/plan.json`,\n  ];\n  for (const candidate of candidates) {\n    const content = readText(workspaceRoot, candidate);\n    if (content) {\n      return JSON.parse(content) as FeaturePlan;\n    }\n  }\n  return null;\n}"
