        "fileContentHash": "52e87fd1320ffe308da24cb17657745d2a9300623f6df15572853271fc3ba092",
        "sourceSlice": "async function readIncomingBody(request: IncomingMessage): Promise<Buffer | undefined> {\n  if (request.method === \"GET\" || request.method === \"HEAD\") {\n    return undefined;\n  }\n\n  const chunks: Buffer[] = [];\n  for await (const chunk of request) {\n    chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));\n  }\n  return chunks.length > 0 ? Buffer.concat(chunks) : undefined;\n}"
