        "exportPath": "export",
        "fileContentHash": "ce24daa5bd2083542d9f675545cd39c94b839bc74b6e470a2b92ffbf50eddc9b",
        "sourceSlice": "function readInstalledVersion(\n  specOrName: string,\n  cwd: string,\n): string | null {\n  const name = parsePackageName(specOrName);\n  let current = cwd;\n  const root = parse(cwd).root;\n\n  while (true) {\n    const version = readVersionAt(packageJsonPath(current, name));\n    if (version) {\n      return version;\n    }\n\n    if (current === root) {\n      return null;\n    }\n\n    const parent = dirname(current);\n    if (parent === current) {\n      return null;\n    }\n    current = parent;\n  }\n}"
