        "sourceSlice": "function recoverStaleLock(lockPath: string): boolean {\n  const ownerPid = readLockOwnerPid(lockPath);\n  if (ownerPid === null || isProcessAlive(ownerPid)) {\n    return false;\n  }\n  rmSync(lockPath, { recursive: true, force: true });\n  return true;\n}"
