        "sourceSlice": "function removeStalePgliteLocks(dataDir: string): void {\n  for (const file of [\n    \"postmaster.pid\",\n    \".s.PGSQL.5432.lock\",\n    \".s.PGSQL.5432.lock.out\",\n  ]) {\n    try {\n      unlinkSync(join(dataDir, file));\n    } catch {\n      // Best effort. If PGlite still cannot open, the caller reports the real open error.\n    }\n  }\n}"
