        "sourceSlice": "function renameRuntimeEntryContent(source: string, file: string, intent: RenameRuntimeEntryIntent): string {\n  if (isTypeScriptLike(file)) {\n    return renameRuntimeEntryInSource(source, file, intent);\n  }\n  if (file.endsWith(\".json\")) {\n    return renameRuntimeEntryInJson(source, intent);\n  }\n  return source;\n}"
