      "meta": {
        "exportPath": "",
        "fileContentHash": "a95522640f9cfd69562a3dbfdd400f3e55da04200ea76b1c4035b844007fe017",
        "sourceSlice": "function renameTableContent(source: string, file: string, intent: Extract<RefactorIntent, { kind: \"renameTable\" }>): string {\n  if (isTypeScriptLike(file)) {\n    return renameTableInSource(source, file, intent.from.table, intent.to.table);\n  }\n  if (file.endsWith(\".json\")) {\n    return renameInJson(source, intent.from.table, intent.to.table, true);\n  }\n  return wordReplace(source, intent.from.table, intent.to.table);\n}"
      },
      "name": "renameTableContent",
      "qualifiedName": "renameTableContent",
      "span": {
        "end": 44787,
        "start": 44365
      }
