        "sourceSlice": "function renderAiOpenaiProvider(_input: IntegrationTemplateInput): string {\n  return [\n    \"/** Forge generated OpenAI provider wiring. */\",\n    'import { createOpenAI } from \"@ai-sdk/openai\";',\n    'import type { SecretsContext } from \"../secretsContext.js\";',\n    \"\",\n    \"export function createForgeOpenAiProvider(secrets: SecretsContext) {\",\n    '  const apiKey = secrets.get(\"OPENAI_API_KEY\");',\n    \"  return createOpenAI({ apiKey });\",\n    \"}\",\n    \"\",\n    'export const forgeOpenAiSecret = \"OPENAI_API_KEY\" as const;',\n    \"\",\n  ].join(\"\\n\");\n}"
