        "sourceSlice": "function renderNuxtStatusComponent(): string {\n  return `<script setup lang=\"ts\">\nimport { computed } from \"vue\";\nimport { useForgeAuth } from \"../composables/forge\";\n\nconst auth = useForgeAuth();\nconst tenantLabel = computed(() => auth?.tenantId ?? \"dev-tenant\");\nconst roleLabel = computed(() => auth?.role ?? \"owner\");\n</script>\n\n<template>\n  <section class=\"status-panel\">\n    <span class=\"status-dot\" aria-hidden=\"true\" />\n    <p>\n      Connected as <strong>{{ roleLabel }}</strong> on\n      <strong>{{ tenantLabel }}</strong>.\n    </p>\n  </section>\n</template>\n\n<style scoped>\n.status-panel {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin-top: 24px;\n  color: #26332d;\n}\n\n.status-dot {\n  width: 10px;\n  height: 10px;\n  border-radius: 999px;\n  background: #1f9d55;\n}\n\np {\n  margin: 0;\n}\n</style>\n`;\n}"
