        "sourceSlice": "function renderPosthogDoc(input: IntegrationTemplateInput): string {\n  return [\n    \"# PostHog integration\",\n    \"\",\n    \"Generated by Forge (recipe v2).\",\n    \"\",\n    \"Client/server split reference.\",\n    \"\",\n    \"## Packages\",\n    \"\",\n    \"- `posthog-js` → client/shared contexts\",\n    \"- `posthog-node` → server/action/workflow contexts\",\n    \"\",\n    \"## Integrations\",\n    \"\",\n    \"- `integrations/posthog/events.ts` — capture helpers\",\n    \"- `integrations/posthog/flags.ts` — feature flag helpers\",\n    \"\",\n    \"## Validation\",\n    \"\",\n    \"- `posthog-js` in client → passes\",\n    \"- `posthog-node` in action → passes\",\n    \"- `posthog-node` in command → `FORGE_GUARD_VIOLATION`\",\n    \"\",\n    `Packages: ${input.packageNames.join(\", \")}`,\n    \"\",\n  ].join(\"\\n\");\n}"
