      "meta": {
        "exportPath": "export",
        "fileContentHash": "bdd6f4a72d334f30bab1f6e9a548e3f748621fabed71431d6c0b2801e543c89f",
        "sourceSlice": "function renderReviewMarkdown(report: ReviewReport): string {\n  const findings = report.findings.map((item) => `- ${item.severity.toUpperCase()} ${item.code}${item.file ? ` (${item.file})` : \"\"}: ${item.message}`).join(\"\\n\") || \"- none\";\n  return `# Forge Review\n\nRisk: ${report.risk.level} (${report.risk.score})\n\n## Summary\n\n${report.summary.bullets.map((bullet) => `- ${bullet}`).join(\"\\n\")}\n\n## Changed Files\n\n${report.changed.files.filter((file) => !file.startsWith(`${GENERATED}/`) && file !== \"forge.lock\").map((file) => `- ${file}`).join(\"\\n\") || \"- none\"}\n\nGenerated artifacts are derived and collapsed by default.\n\n- Generated files: ${report.diffPlan.generatedFiles}\n- Authored diff: \\`${report.diffPlan.authoredDiffCommand}\\`\n- Generated diff: \\`${report.diffPlan.generatedDiffCommand}\\`\n\n## Findings\n\n${findings}\n\n## Recommended Commands\n\n\\`\\`\\`bash\n${report.recommendedCommands.join(\"\\n\")}\n\\`\\`\\`\n`;\n}"
      },
