        "sourceSlice": "function renderSentryDoc(input: IntegrationTemplateInput): string {\n  const framework = input.recipe.frameworkTarget ?? \"nextjs\";\n  return [\n    \"# Sentry integration\",\n    \"\",\n    \"Generated by Forge (recipe v2).\",\n    \"\",\n    `Framework target: **${framework}** (uses \\`@sentry/nextjs\\`).`,\n    \"\",\n    \"## Integrations\",\n    \"\",\n    \"- `integrations/sentry/errors.ts` — server/action error capture\",\n    \"- `integrations/sentry/releases.ts` — release tracking\",\n    \"- `integrations/sentry/sourcemaps.ts` — source map env vars for CI\",\n    \"\",\n    \"## Source map env vars\",\n    \"\",\n    \"- `SENTRY_AUTH_TOKEN`\",\n    \"- `SENTRY_ORG`\",\n    \"- `SENTRY_PROJECT`\",\n    \"\",\n    \"## Validation\",\n    \"\",\n    \"- Sentry server capture in `action` → passes\",\n    \"- Direct Sentry capture in `command` → `FORGE_GUARD_VIOLATION`\",\n    \"\",\n  ].join(\"\\n\");\n}"
