        "sourceSlice": "function renderSentryErrors(_input: IntegrationTemplateInput): string {\n  return [\n    \"/** Forge generated Sentry error capture helpers. */\",\n    'import * as Sentry from \"@sentry/nextjs\";',\n    \"\",\n    \"export function captureActionError(error: unknown, context?: Record<string, unknown>) {\",\n    \"  if (context) {\",\n    \"    Sentry.withScope((scope) => {\",\n    \"      for (const [key, value] of Object.entries(context)) {\",\n    \"        scope.setExtra(key, value);\",\n    \"      }\",\n    \"      Sentry.captureException(error);\",\n    \"    });\",\n    \"    return;\",\n    \"  }\",\n    \"  Sentry.captureException(error);\",\n    \"}\",\n    \"\",\n  ].join(\"\\n\");\n}"
