        "sourceSlice": "function renderVitePackage(appName: string): string {\n  return `{\n  \"name\": \"${kebabCase(appName)}-web\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"vite --host 127.0.0.1\",\n    \"build\": \"vite build\",\n    \"typecheck\": \"tsc --noEmit\"\n  },\n  \"dependencies\": {\n    \"@ai-sdk/react\": \"^3.0.0\",\n    \"@vitejs/plugin-react\": \"^6.0.2\",\n    \"ai\": \"^6.0.0\",\n    \"vite\": \"^8.0.16\",\n    \"react\": \"^19.0.0\",\n    \"react-dom\": \"^19.0.0\"\n  },\n  \"devDependencies\": {\n    \"@types/react\": \"^19.0.0\",\n    \"@types/react-dom\": \"^19.0.0\",\n    \"typescript\": \"^5.7.3\"\n  }\n}\n`;\n}"
