      "id": "76d6add0740e65a4093ade8dde26174ca622a17759448e677bb3738670c9aa80",
      "kind": "code.function",
      "meta": {
        "exportPath": "",
        "fileContentHash": "8f7afe9b75d8171ed3e72183b146f9e76e4be9ed57fa70ff44ae45151be118d1",
        "sourceSlice": "function renderWebDockerfile(): string {\n  return `FROM oven/bun:1 AS base\nWORKDIR /app\n\nFROM base AS deps\nCOPY package.json bun.lock* ./\nCOPY web/package.json web/package.json\nRUN bun install --frozen-lockfile\n\nFROM base AS build\nWORKDIR /app\nCOPY --from=deps /app/node_modules ./node_modules\nCOPY . .\nWORKDIR /app/web\nRUN bun run build\n\nFROM node:22-slim AS runtime\nWORKDIR /app\nENV NODE_ENV=production\nCOPY --from=build /app/web/.next/standalone ./\nCOPY --from=build /app/web/.next/static ./.next/static\nCOPY --from=build /app/web/public ./public\nEXPOSE 3000\nCMD [\"node\", \"server.js\"]\n`;\n}"
      },
