        "sourceSlice": "function renderWorkosSeed(_input: IntegrationTemplateInput): string {\n  return [\n    \"/** Forge generated WorkOS seed metadata. */\",\n    \"\",\n    \"export const workosSeedFile = \\\"workos-seed.yml\\\" as const;\",\n    \"\",\n    \"export const workosSeedCommands = [\",\n    \"  `npx workos@latest seed --file ${workosSeedFile}`,\",\n    \"  `npx workos@latest seed --file ${workosSeedFile} --clean`,\",\n    \"] as const;\",\n    \"\",\n    \"export const workosSeedStateFile = \\\".workos-seed-state.json\\\" as const;\",\n    \"\",\n  ].join(\"\\n\");\n}"
