      "id": "20bdd420a882035a5272c70f0e272a8ebddf1fa4a4b7a971cf01fca819751a70",
      "kind": "code.function",
      "meta": {
        "exportPath": "export",
        "fileContentHash": "60b6cb3b1a277eae20a3f5b31e0afb8271dd7ff08c7311fe4ff1521b14532169",
        "sourceSlice": "function renderWorkosSession(_input: IntegrationTemplateInput): string {\n  return [\n    \"/** Forge generated WorkOS AuthKit session helpers. */\",\n    'import type { ForgeWorkOSAuthKitConfig } from \"../../packages/workos.server.js\";',\n    \"\",\n    \"export interface ForgeWorkOSSession {\",\n    \"  user: { id: string; email?: string; firstName?: string; lastName?: string; [key: string]: unknown };\",\n    \"  accessToken: string;\",\n    \"  refreshToken?: string;\",\n    \"  organizationId?: string;\",\n    \"  organizationMembershipId?: string;\",\n    \"  role?: string;\",\n    \"  roles?: string[];\",\n    \"  permissions?: string[];\",\n    \"  issuedAt: number;\",\n    \"}\",\n    \"\",\n    \"export interface ForgeWorkOSClaims {\",\n    \"  sub: string;\",\n    \"  email?: string;\",\n    \"  name?: string;\",\n    \"  organization_id?: string;\",\n    \"  organization_membership_id?: string;\",\n    \"  role?: string;\",\n    \"  roles?: string[];\",\n    \"  permissions?: string[];\",\n    \"}\",\n    \"\",\n    \"function bytesToBase64url(bytes: Uint8Array): string {\",\n    \"  let binary = \\\"\\\";\",\n    \"  for (const byte of bytes) binary += String.fromCharCode(byte);\",\n    \"  return btoa(binary).replace(/\\\\+/g, \\\"-\\\").replace(/\\\\//g, \\\"_\\\").replace(/=+$/g, \\\"\\\");\",\n    \"}\",\n    \"\",\n    \"function base64urlToBytes(input: string): Uint8Array {\",\n    \"  const padded = input.replace(/-/g, \\\"+\\\").replace(/_/g, \\\"/\\\").padEnd(Math.ceil(input.length / 4) * 4, \\\"=\\\");\",\n    \"  return Uint8Array.from(atob(padded), (char) => char.charCodeAt(0));\",\n    \"}\",\n    \"\",\n    \"function base64url(input: string): string {\",\n    \"  return bytesToBase64url(new TextEncoder().encode(input));\",\n    \"}\",\n    \"\",\n    \"function fromBase64url(input: string): string {\",\n    \"  return new TextDecoder().decode(base64urlToBytes(input));\",\n    \"}\",\n    \"\",\n    \"async function sign(payload: string, secret: string): Promise<string> {\",\n    \"  const key = await crypto.subtle.importKey(\",\n    \"    \\\"raw\\\",\",\n    \"    new TextEncoder().encode(secret),\",\n    \"    { name: \\\"HMAC\\\", hash: \\\"SHA-256\\\" },\",\n    \"    false,\",\n    \"    [\\\"sign\\\"],\",\n    \"  );\",\n    \"  const signature = await crypto.subtle.sign(\\\"HMAC\\\", key, new TextEncoder().encode(payload));\",\n    \"  return bytesToBase64url(new Uint8Array(signature));\",\n    \"}\",\n    \"\",\n    \"function safeEqual(a: string, b: string): boolean {\",\n    \"  if (a.length !== b.length) return false;\",\n    \"  let diff = 0;\",\n    \"  for (let index = 0; index < a.length; index += 1) diff |= a.charCodeAt(index) ^ b.charCodeAt(index);\",\n    \"  return diff === 0;\",\n    \"}\",\n    \"\",\n    \"export async function encodeWorkOSSession(session: ForgeWorkOSSession, cookiePassword: string): Promise<string> {\",\n    \"  const payload = base64url(JSON.stringify(session));\",\n    \"  return `${payload}.${await sign(payload, cookiePassword)}`;\",\n    \"}\",\n    \"\",\n    \"export async function decodeWorkOSSession(value: string | undefined, cookiePassword: string): Promise<ForgeWorkOSSession | null> {\",\n    \"  if (!value) return null;\",\n    \"  const [payload, signature] = value.split(\\\".\\\");\",\n    \"  if (!payload || !signature || !safeEqual(signature, await sign(payload, cookiePassword))) return null;\",\n    \"  return JSON.parse(fromBase64url(payload)) as ForgeWorkOSSession;\",\n    \"}\",\n    \"\",\n    \"export function readCookie(header: string | null | undefined, name: string): string | undefined {\",\n    \"  return (header ?? \\\"\\\")\",\n    \"    .split(\\\";\\\")\",\n    \"    .map((part) => part.trim())\",\n    \"    .find((part) => part.startsWith(`${name}=`))\",\n    \"    ?.slice(name.length + 1);\",\n    \"}\",\n    \"\",\n    \"export function sessionCookieName(config: ForgeWorkOSAuthKitConfig): string {\",\n    \"  return config.cookieName || \\\"forgeos_workos_session\\\";\",\n    \"}\",\n    \"\",\n    \"export async function createWorkOSSessionCookie(config: ForgeWorkOSAuthKitConfig, session: ForgeWorkOSSession): Promise<string> {\",\n    \"  const value = await encodeWorkOSSession(session, config.cookiePassword);\",\n    \"  return `${sessionCookieName(config)}=${value}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=2592000`;\",\n    \"}\",\n    \"\",\n    \"export function clearWorkOSSessionCookie(config: ForgeWorkOSAuthKitConfig): string {\",\n    \"  return `${sessionCookieName(config)}=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0`;\",\n    \"}\",\n    \"\",\n    \"export function workOSSessionToClaims(session: ForgeWorkOSSession): ForgeWorkOSClaims {\",\n    \"  return {\",\n    \"    sub: session.user.id,\",\n    \"    ...(session.user.email ? { email: String(session.user.email) } : {}),\",\n    \"    ...(session.user.firstName || session.user.lastName ? { name: [session.user.firstName, session.user.lastName].filter(Boolean).join(\\\" \\\") } : {}),\",\n    \"    ...(session.organizationId ? { organization_id: session.organizationId } : {}),\",\n    \"    ...(session.organizationMembershipId ? { organization_membership_id: session.organizationMembershipId } : {}),\",\n    \"    ...(session.role ? { role: session.role } : {}),\",\n    \"    ...(session.roles ? { roles: session.roles } : {}),\",\n    \"    ...(session.permissions ? { permissions: session.permissions } : {}),\",\n    \"  };\",\n    \"}\",\n    \"\",\n  ].join(\"\\n\");\n}"
      },
      "name": "renderWorkosSession",
      "qualifiedName": "renderWorkosSession",
