        "sourceSlice": "function replacementFromMatch(replacement: string, match: RegExpExecArray): string {\n  let index = 1;\n  return replacement.replace(/\\$\\$\\$[A-Z_][A-Z0-9_]*/gi, () => match[index++] ?? \"\");\n}"
