        "fileContentHash": "8f7afe9b75d8171ed3e72183b146f9e76e4be9ed57fa70ff44ae45151be118d1",
        "sourceSlice": "function requiredEnvNames(workspaceRoot: string): string[] {\n  const secretRegistry = readGeneratedJson<{ secrets?: Array<{ name: string }> }>(\n    workspaceRoot,\n    `${GENERATED_DIR}/secretRegistry.json`,\n  );\n  const envSchema = readGeneratedJson<{ variables?: Array<{ name: string }> }>(\n    workspaceRoot,\n    `${GENERATED_DIR}/envSchema.json`,\n  );\n\n  const names = new Set([\n    \"DATABASE_URL\",\n    \"FORGE_ENV\",\n    \"FORGE_PORT\",\n    \"FORGE_RELEASE_ID\",\n    \"FORGE_DEPLOY_ID\",\n    \"FORGE_DEPLOY_ENV\",\n    \"FORGE_LIVE_TRANSPORT\",\n    \"FORGE_LIVE_INVALIDATION\",\n    \"FORGE_LIVE_POLL_INTERVAL_MS\",\n    \"FORGE_LIVE_HEARTBEAT_MS\",\n    \"FORGE_AUTH_MODE\",\n    \"FORGE_AUTH_ISSUER\",\n    \"FORGE_AUTH_AUDIENCE\",\n    \"FORGE_AUTH_JWKS_URI\",\n    \"FORGE_AUTH_ALGORITHMS\",\n    \"NEXT_PUBLIC_FORGE_URL\",\n    \"NEXT_PUBLIC_FORGE_RELEASE_ID\",\n    \"POSTHOG_KEY\",\n    \"POSTHOG_HOST\",\n    \"SENTRY_DSN\",\n    \"SENTRY_AUTH_TOKEN\",\n    \"SENTRY_ORG\",\n    \"SENTRY_PROJECT\",\n    \"STRIPE_SECRET_KEY\",\n    \"STRIPE_WEBHOOK_SECRET\",\n    \"OPENAI_API_KEY\",\n    \"ANTHROPIC_API_KEY\",\n    \"AI_GATEWAY_API_KEY\",\n  ]);\n\n  for (const secret of secretRegistry?.secrets ?? []) {\n    names.add(secret.name);\n  }\n  for (const variable of envSchema?.variables ?? []) {\n    names.add(variable.name);\n  }\n\n  return [...names].sort();\n}"
