      "file": "src/forge/runtime/db/migrate.ts",
      "id": "04594bc7aa9acd4f317464154ecde78488690577be787910aaf3446a9709afd7",
      "kind": "code.function",
      "meta": {
        "exportPath": "export",
        "fileContentHash": "5358822201b60c18f293daf7baa815a8c3c072559844b18de443306d0451a582",
        "sourceSlice": "async function resetDatabase(\n  adapter: DbAdapter,\n  sqlPlan: SqlPlan,\n): Promise<Diagnostic[]> {\n  const diagnostics: Diagnostic[] = [];\n\n  try {\n    for (const change of [...sqlPlan.tables].reverse()) {\n      if (change.table) {\n        await adapter.query(`DROP TABLE IF EXISTS \"${change.table}\" CASCADE`);\n      }\n    }\n\n    await adapter.query(`TRUNCATE TABLE _forge_migrations`);\n    await adapter.query(`TRUNCATE TABLE _forge_trace_spans RESTART IDENTITY CASCADE`);\n    await adapter.query(`TRUNCATE TABLE _forge_telemetry_events RESTART IDENTITY CASCADE`);\n    await adapter.query(`TRUNCATE TABLE _forge_live_subscription_debug RESTART IDENTITY CASCADE`);\n    await adapter.query(`TRUNCATE TABLE _forge_live_invalidations RESTART IDENTITY CASCADE`);\n    await adapter.query(`TRUNCATE TABLE _forge_workflow_steps RESTART IDENTITY CASCADE`);\n    await adapter.query(`TRUNCATE TABLE _forge_workflow_runs RESTART IDENTITY CASCADE`);\n    await adapter.query(`TRUNCATE TABLE _forge_outbox_deliveries RESTART IDENTITY CASCADE`);\n    await adapter.query(`TRUNCATE TABLE _forge_outbox RESTART IDENTITY CASCADE`);\n\n    diagnostics.push(...(await applyMigrations(adapter, sqlPlan)));\n  } catch (error) {\n    const message = error instanceof Error ? error.message : \"database reset failed\";\n    diagnostics.push(\n      createDiagnostic({\n        severity: \"error\",\n        code: FORGE_DB_MIGRATION_FAILED,\n        message,\n      }),\n    );\n  }\n\n  return diagnostics;\n}"
      },
      "name": "resetDatabase",
      "qualifiedName": "resetDatabase",
      "span": {
        "end": 3147,
        "start": 1682
      }
