        "fileContentHash": "511a071e355d2bae7caae4f678008acd61e2cea008edea32328d556643fedd79",
        "sourceSlice": "function resolveCodexExecutable(requested: string): ResolvedCodexExecutable {\n  if (process.platform !== \"win32\") {\n    return { requested, executable: requested, strategy: \"direct\" };\n  }\n\n  if (hasPathSeparator(requested) || isAbsolute(requested)) {\n    const extension = extname(requested).toLowerCase();\n    return {\n      requested,\n      executable: requested,\n      strategy: extension === \".cmd\" || extension === \".bat\"\n        ? \"cmd-shim\"\n        : extension === \".ps1\"\n          ? \"powershell-shim\"\n          : \"direct\",\n    };\n  }\n\n  const pathEntries = (process.env.PATH ?? \"\")\n    .split(delimiter)\n    .map((entry) => entry.trim())\n    .filter(Boolean);\n  const candidates = [\n    `${requested}.cmd`,\n    `${requested}.exe`,\n    `${requested}.bat`,\n    `${requested}.ps1`,\n    requested,\n  ];\n  for (const entry of pathEntries) {\n    for (const candidate of candidates) {\n      const absolute = join(entry, candidate);\n      if (!existsSync(absolute) || !safeStatFile(absolute)) {\n        continue;\n      }\n      const extension = extname(absolute).toLowerCase();\n      return {\n        requested,\n        executable: absolute,\n        strategy: extension === \".cmd\" || extension === \".bat\"\n          ? \"cmd-shim\"\n          : extension === \".ps1\"\n            ? \"powershell-shim\"\n            : \"path\",\n        ...(extension === \"\" ? { warning: \"resolved to an extensionless Windows shim; prefer a .cmd or .exe path with FORGE_CODEX_BIN\" } : {}),\n      };\n    }\n  }\n  return { requested, executable: requested, strategy: \"direct\" };\n}"
