      "meta": {
        "exportPath": "",
        "fileContentHash": "0c5bb8beac5f474d11d797cf7e572becfa7fe31b814860675a27190ea062e167",
        "sourceSlice": "function resolveLocalTarget(\n  specifier: string,\n  fromFile: string,\n  sourcePaths: Set<string>,\n): string | null {\n  if (!specifier.startsWith(\".\")) {\n    return null;\n  }\n\n  const base = normalizePath(path.join(path.dirname(fromFile), specifier));\n  const candidates = [\n    base,\n    `${base}.ts`,\n    `${base}.tsx`,\n    `${base}/index.ts`,\n    `${base}/index.tsx`,\n  ];\n  if (/\\.[cm]?jsx?$/.test(base)) {\n    const withoutJsExtension = base.replace(/\\.[cm]?jsx?$/, \"\");\n    candidates.push(\n      `${withoutJsExtension}.ts`,\n      `${withoutJsExtension}.tsx`,\n    );\n  }\n\n  return candidates.find((candidate) => sourcePaths.has(candidate)) ?? null;\n}"
      },
