        "fileContentHash": "c37bfbb95047794938b6b9f567d912fb9509a1ea4b3e3dea99da788cbe5e3269",
        "sourceSlice": "function resolveRecipe(alias: string): IntegrationRecipe | null {\n  const normalized = alias.trim().toLowerCase();\n  const direct = REFERENCE_RECIPES[normalized];\n  if (direct) return direct;\n\n  const provider = AI_PROVIDER_RECIPES.find(\n    (r) =>\n      r.alias.toLowerCase() === normalized ||\n      r.alias === alias ||\n      r.packages.some((pkg) => pkg.packageName.toLowerCase() === normalized),\n  );\n  if (provider) return provider;\n\n  return null;\n}"
