        "sourceSlice": "function resolveRelativeRuntimeImport(fromFile: string, specifier: string): string {\n  const base = resolve(dirname(fromFile), specifier);\n  const candidates = [\n    base,\n    `${base}.ts`,\n    `${base}.tsx`,\n    `${base}.js`,\n    `${base}.jsx`,\n    join(base, \"index.ts\"),\n    join(base, \"index.tsx\"),\n    join(base, \"index.js\"),\n    join(base, \"index.jsx\"),\n  ];\n  return candidates.find((candidate) => nodeFileSystem.exists(candidate)) ?? base;\n}"
