        "sourceSlice": "function resolveSystemAuthFromDelivery(delivery: ClaimedDelivery): AuthContext {\n  const snapshot = (delivery.auth_context as AuthContext | undefined) ?? { kind: \"anonymous\" };\n  const tenantId =\n    snapshot.kind === \"user\"\n      ? snapshot.tenantId\n      : snapshot.kind === \"system\"\n        ? snapshot.tenantId\n        : undefined;\n  return systemAuthFromSnapshot(snapshot, tenantId);\n}"
