        "sourceSlice": "function resolveTenantId(\n  auth: AuthContext | undefined,\n  entry: TableMapEntry,\n): string | null {\n  if (!entry.tenantScoped || !entry.tenantIdColumn) {\n    return null;\n  }\n\n  if (auth?.kind === \"user\") {\n    return auth.tenantId ?? null;\n  }\n\n  if (auth?.kind === \"system\" && auth.tenantId) {\n    return auth.tenantId;\n  }\n\n  return null;\n}"
