        "sourceSlice": "function resourcePolicyRoles(resource: ResourceBlueprint): string | undefined {\n  const roles = new Set<string>();\n  for (const values of Object.values(resource.policies ?? {})) {\n    for (const role of values ?? []) {\n      roles.add(role);\n    }\n  }\n  if (roles.size === 0) {\n    return undefined;\n  }\n  return [...roles].sort().join(\",\");\n}"
