        "fileContentHash": "ae8d7b86b06c12c082ddd62bd5df8b62490e667331340d88d4205a5ed490a2d4",
        "sourceSlice": "function restoreEnv(snapshot: Record<string, string | undefined>): void {\n  for (const key of Object.keys(process.env)) {\n    if (!(key in snapshot)) {\n      delete process.env[key];\n    }\n  }\n  for (const [key, value] of Object.entries(snapshot)) {\n    if (value === undefined) {\n      delete process.env[key];\n    } else {\n      process.env[key] = value;\n    }\n  }\n}"
