        "fileContentHash": "d6c85accdfabd5ce141bd36fba1fcd6a3f6402c292ced750d0a49ac2e8f0ddb4",
        "sourceSlice": "function restoreSnapshot(workspaceRoot: string, plan: RepairPlan): void {\n  const snapshot = readJson<{ files: Array<{ file: string; existed: boolean; content: string | null }> }>(\n    workspaceRoot,\n    plan.rollback.snapshotFile,\n  );\n  if (!snapshot) {\n    return;\n  }\n  for (const file of snapshot.files) {\n    const absolute = join(workspaceRoot, normalize(file.file));\n    if (!file.existed) {\n      nodeFileSystem.remove(absolute);\n      continue;\n    }\n    nodeFileSystem.writeText(absolute, file.content ?? \"\");\n  }\n}"
