        "sourceSlice": "function resultBase(options: SeedCommandOptions, commands: RuntimeEntry[]): Omit<SeedCommandResult, \"ok\" | \"diagnostics\" | \"nextActions\" | \"exitCode\"> {\n  const selected = selectSeedCommand(commands, options.command);\n  return {\n    schemaVersion: \"0.1.0\",\n    subcommand: options.subcommand,\n    url: runtimeUrl(options),\n    readiness: buildReadiness(options, commands),\n    selectedCommand: selected?.name,\n    commands: commands.map((entry) => ({\n      name: entry.name,\n      file: entry.file,\n      selected: entry.name === selected?.name,\n    })),\n  };\n}"
