        "sourceSlice": "function roleAllowed(\n  matrix: PermissionMatrix,\n  policy: string,\n  roles: string[],\n): boolean {\n  const entry = matrix.entries.find((candidate) => candidate.policy === policy);\n  if (!entry) {\n    return false;\n  }\n  return roles.some((role) => entry.roles.includes(role));\n}"
