        "sourceSlice": "function rollbackUpgradePlan(options: {\n  workspaceRoot: string;\n  planPath: string;\n}): UpgradeApplyResult {\n  const diagnostics: Diagnostic[] = [];\n  try {\n    const plan = readPlan(options.planPath);\n    restoreSnapshot(options.workspaceRoot, plan);\n    return {\n      ok: true,\n      plan,\n      diagnostics,\n      applied: false,\n      rolledBack: true,\n      exitCode: 0,\n    };\n  } catch (error) {\n    diagnostics.push(\n      createDiagnostic({\n        severity: \"error\",\n        code: FORGE_DEPS_ROLLBACK_FAILED,\n        message: error instanceof Error ? error.message : \"rollback failed\",\n      }),\n    );\n    return {\n      ok: false,\n      plan: null,\n      diagnostics,\n      applied: false,\n      rolledBack: false,\n      exitCode: 1,\n    };\n  }\n}"
