        "fileContentHash": "aeade6163f7acf6db36e88c9f2adeb5ba6dab9def290acdaee76fe72a4b2c441",
        "sourceSlice": "async function runDevConsoleCycle(options: DevConsoleOptions): Promise<DevConsoleCycle> {\n  resetCompileSessions();\n  const workspaceRoot = options.workspaceRoot.replace(/\\\\/g, \"/\");\n  const phases: DevConsolePhase[] = [];\n  const generated = await runGeneratedPhase(workspaceRoot, options.generatedMode ?? \"write\");\n  phases.push(generated);\n  if (generated.ok) {\n    phases.push(await runCheckPhase(workspaceRoot, options.strictSecrets ?? false));\n    phases.push(runFrontendPhase(workspaceRoot, {\n      ...(options.apiUrl ? { apiUrl: options.apiUrl } : {}),\n      ...(options.webUrl ? { webUrl: options.webUrl } : {}),\n    }));\n  } else {\n    phases.push(\n      skippedPhase(\n        \"check\",\n        \"skipped until generated artifacts are in sync\",\n      ),\n    );\n    phases.push(\n      skippedPhase(\n        \"frontend\",\n        \"skipped until generated frontend graph is in sync\",\n      ),\n    );\n  }\n  phases.push(runDoctorPhase(workspaceRoot));\n  if (options.includeImpact ?? true) {\n    phases.push(runImpactPhase(workspaceRoot));\n  }\n  phases.push(runLastTestPhase(workspaceRoot));\n  phases.push(runLastUiPhase(workspaceRoot));\n\n  const normalizedPhases = phases.map((item) => normalizePhaseCommands(workspaceRoot, item));\n  const diagnostics = normalizedPhases.flatMap((item) => item.diagnostics);\n  const ok = normalizedPhases.every((item) => item.ok);\n  const nextActions = nextActionsFromPhases(workspaceRoot, normalizedPhases);\n  const summary = buildDevSummary({\n    workspaceRoot,\n    ok,\n    phases: normalizedPhases,\n    diagnostics,\n    nextActions,\n    ...(options.apiUrl ? { apiUrl: options.apiUrl } : {}),\n    ...(options.webUrl ? { webUrl: options.webUrl } : {}),\n  });\n  return {\n    schemaVersion: \"0.1.0\",\n    ok,\n    mode: options.mode,\n    summary,\n    phases: normalizedPhases,\n    diagnostics,\n    nextActions,\n    exitCode: ok ? 0 : 1,\n  };\n}"
