        "fileContentHash": "c0cc4c1f6cef9ffd4419f085ff83f6396ed411555c48ee20b6513e4017070e49",
        "sourceSlice": "function runDevStatus(options: DevCommandOptions): DevCommandResult {\n  const paths = devStatePaths(options.workspaceRoot);\n  const pid = readDetachedDevPid(options.workspaceRoot);\n  const running = pid !== null && isProcessRunning(pid);\n  if (pid !== null && !running) {\n    removeDevPidFile(options.workspaceRoot);\n  }\n  return printDevLifecycleResult({\n    options,\n    ok: true,\n    action: \"status\",\n    running,\n    ...(pid !== null ? { pid } : {}),\n    ...(pid !== null && running ? { process: processDetails(pid) } : {}),\n    logFile: paths.logFile,\n    message: running ? \"forge dev detached server is running\" : \"forge dev detached server is not running\",\n    exitCode: 0,\n  });\n}"
