        "fileContentHash": "c0cc4c1f6cef9ffd4419f085ff83f6396ed411555c48ee20b6513e4017070e49",
        "sourceSlice": "function runDevStop(options: DevCommandOptions): DevCommandResult {\n  const paths = devStatePaths(options.workspaceRoot);\n  const pid = readDetachedDevPid(options.workspaceRoot);\n  if (pid === null || !isProcessRunning(pid)) {\n    removeDevPidFile(options.workspaceRoot);\n    return printDevLifecycleResult({\n      options,\n      ok: true,\n      action: \"stop\",\n      running: false,\n      ...(pid !== null ? { pid } : {}),\n      ...(pid !== null ? { process: processDetails(pid) } : {}),\n      logFile: paths.logFile,\n      message: \"no detached forge dev server was running\",\n      exitCode: 0,\n    });\n  }\n  process.kill(pid, \"SIGTERM\");\n  removeDevPidFile(options.workspaceRoot);\n  return printDevLifecycleResult({\n    options,\n    ok: true,\n    action: \"stop\",\n    running: false,\n    pid,\n    process: processDetails(pid),\n    logFile: paths.logFile,\n    message: \"stopped detached forge dev server\",\n    exitCode: 0,\n  });\n}"
