        "sourceSlice": "async function runGenerateChecks(options: FeatureCommandOptions): Promise<Diagnostic[]> {\n  const diagnostics: Diagnostic[] = [];\n  if (!options.noGenerate) {\n    const generated = await run({\n      workspaceRoot: options.workspaceRoot,\n      check: false,\n      dryRun: false,\n      json: false,\n      concurrency: 4,\n    });\n    diagnostics.push(...generated.errors, ...generated.warnings);\n  }\n  if (!options.noVerify) {\n    const check = await run({\n      workspaceRoot: options.workspaceRoot,\n      check: true,\n      dryRun: false,\n      json: false,\n      concurrency: 4,\n    });\n    diagnostics.push(...check.errors, ...check.warnings);\n    if (check.exitCode !== 0) {\n      diagnostics.push(\n        diagnostic(\n          \"error\",\n          \"FORGE_FEATURE_BLUEPRINT_INVALID\",\n          \"post-apply forge generate --check failed\",\n        ),\n      );\n    }\n  }\n  return diagnostics;\n}"
