        "sourceSlice": "function runLastCommand(options: { workspaceRoot: string }): LastRunCommandResult {\n  const path = lastRunPath(options.workspaceRoot);\n  const record = readLastRunRecord(options.workspaceRoot);\n  return {\n    ok: record !== null,\n    record,\n    path,\n    exitCode: record ? 0 : 1,\n  };\n}"
