      "meta": {
        "exportPath": "export",
        "fileContentHash": "373496c4e054a7f11e11f32391f6036bb0f371c2616157d7d00f489ebdc747b0",
        "sourceSlice": "function runUiListCommand(workspaceRoot: string): UiCommandResult {\n  return {\n    ok: true,\n    reports: listUiRuns(workspaceRoot),\n    diagnostics: [],\n    exitCode: 0,\n  };\n}"
      },
