        "sourceSlice": "function runUsageDiagnostic(): ReturnType<typeof createDiagnostic> {\n  return createDiagnostic({\n    severity: \"error\",\n    code: \"FORGE_CLI_USAGE\",\n    message: \"forge run requires an entry name, or use --list\",\n  });\n}"
