        "sourceSlice": "function runtimeEntryRisk(kind: RuntimeEntryKind, entry: RuntimeEntry): string {\n  if (entry.risk) {\n    return entry.risk;\n  }\n  if (kind === \"command\") {\n    return \"write\";\n  }\n  if (kind === \"action\") {\n    return \"external\";\n  }\n  return \"read\";\n}"
