        "sourceSlice": "function selectSeedCommand(commands: RuntimeEntry[], requested?: string): RuntimeEntry | undefined {\n  if (requested) {\n    return commands.find((entry) => entry.name === requested);\n  }\n  return commands[0];\n}"
