        "sourceSlice": "function splitTopLevel(value: string, separator = \",\"): string[] {\n  const parts: string[] = [];\n  let current = \"\";\n  let depth = 0;\n  for (const char of value) {\n    if (char === \"(\") {\n      depth += 1;\n    } else if (char === \")\") {\n      depth = Math.max(0, depth - 1);\n    }\n    if (char === separator && depth === 0) {\n      if (current.trim()) {\n        parts.push(current.trim());\n      }\n      current = \"\";\n      continue;\n    }\n    current += char;\n  }\n  if (current.trim()) {\n    parts.push(current.trim());\n  }\n  return parts;\n}"
