        "fileContentHash": "55607bd9392802113f68c12850a842c2771fce0ef3e7b1932e03ad9e12e3ad74",
        "sourceSlice": "async function startTraceSpan(\n  target: QueryTarget,\n  input: {\n    traceId: string;\n    spanId: string;\n    parentSpanId?: string;\n    name: string;\n    kind: TelemetryRuntimeKind;\n    attributes?: Record<string, unknown>;\n    startedAt?: string;\n  },\n): Promise<void> {\n  await target.query(\n    `INSERT INTO _forge_trace_spans (trace_id, parent_span_id, span_id, name, kind, attributes, status, started_at)\n     VALUES ($1, $2, $3, $4, $5, $6::jsonb, 'ok', $7)`,\n    [\n      input.traceId,\n      input.parentSpanId ?? null,\n      input.spanId,\n      input.name,\n      input.kind,\n      JSON.stringify(input.attributes ?? {}),\n      input.startedAt ?? new Date().toISOString(),\n    ],\n  );\n}"
