        "sourceSlice": "function summarizeTimelineArtifacts(artifacts: Record<string, unknown>[]): Record<string, unknown> | undefined {\n  if (artifacts.length === 0) {\n    return undefined;\n  }\n  const sample = artifacts.slice(0, 10).map((artifact) => ({\n    path: artifact.path,\n    artifactKind: artifact.artifact_kind,\n    hash: artifact.hash,\n    generated: artifact.generated,\n  }));\n  return {\n    count: artifacts.length,\n    hash: hashStable(JSON.stringify(artifacts.map((artifact) => ({\n      path: artifact.path,\n      artifactKind: artifact.artifact_kind,\n      hash: artifact.hash,\n      generated: artifact.generated,\n    })))),\n    sample,\n    omitted: Math.max(0, artifacts.length - sample.length),\n  };\n}"
