      "kind": "code.function",
      "meta": {
        "exportPath": "export",
        "fileContentHash": "a7dffaedc06bcceb2a6442ddd5d4fc6e3c9a851ffd13d985cbf17fbcb30470c7",
        "sourceSlice": "function symbolicateStacktrace(input: {\n  workspaceRoot: string;\n  manifest: SourceMapManifest;\n  stacktrace: StacktraceInput;\n}): SymbolicationResult {\n  const frames: SymbolicatedFrame[] = [];\n  const diagnostics = [];\n\n  for (const frame of input.stacktrace.frames) {\n    const sourceMapPath = findSourceMap(input.workspaceRoot, input.manifest, frame.file);\n    if (!sourceMapPath) {\n      frames.push({ generated: frame });\n      diagnostics.push(\n        createDiagnostic({\n          severity: \"warning\",\n          code: FORGE_SOURCEMAP_SYMBOLICATION_FAILED,\n          message: `no source map found for ${frame.file}`,\n        }),\n      );\n      continue;\n    }\n\n    try {\n      const map = JSON.parse((nodeFileSystem.readText(sourceMapPath) ?? \"\")) as SourceMapV3;\n      frames.push({\n        generated: frame,\n        original: symbolicateFrame(map, frame),\n      });\n    } catch (error) {\n      frames.push({ generated: frame });\n      diagnostics.push(\n        createDiagnostic({\n          severity: \"warning\",\n          code: FORGE_SOURCEMAP_SYMBOLICATION_FAILED,\n          message: error instanceof Error ? error.message : \"source map parse failed\",\n        }),\n      );\n    }\n  }\n\n  return { frames, diagnostics };\n}"
      },
      "name": "symbolicateStacktrace",
      "qualifiedName": "symbolicateStacktrace",
      "span": {
        "end": 5011,
        "start": 3783
      }
