      "meta": {
        "exportPath": "",
        "fileContentHash": "2cc33bb06f6026f9abd223c4b32383fd51dbe02054a59d267ac9c416359890d9",
        "sourceSlice": "function testsObservation(snapshot: CairSnapshot, arg: string | undefined, kv: Map<string, string>): CairObservation {\n  const symbol = findSymbol(snapshot, arg, kv);\n  if (!symbol) {\n    return observation(\"O TESTS\", \"matches=0 reason=symbol_not_found\", { tests: [] });\n  }\n  const tests = testsForSymbol(snapshot, symbol);\n  return observation(\n    \"O TESTS\",\n    [\n      `symbol=${symbol.id}`,\n      `matches=${tests.length}`,\n      tests.length > 0 ? `tests=${tests.map((test) => test.id).join(\",\")}` : \"tests=none\",\n    ].join(\" \"),\n    { symbol, tests },\n  );\n}"
      },
