      "meta": {
        "exportPath": "",
        "fileContentHash": "692cf9b144dd27bcfe5083997f24d1786d6b522449987e44dfcf8175b394d5ad",
        "sourceSlice": "function truncateString(\n  value: string,\n  maxBytes: number,\n  diagnostics: Diagnostic[],\n  field: string,\n): string {\n  const encoded = Buffer.byteLength(value, \"utf8\");\n  if (encoded <= maxBytes) {\n    return value;\n  }\n\n  diagnostics.push(\n    createDiagnostic({\n      severity: \"warning\",\n      code: FORGE_TELEMETRY_PAYLOAD_TRUNCATED,\n      message: `truncated telemetry ${field} from ${encoded} to ${maxBytes} bytes`,\n    }),\n  );\n\n  let truncated = value;\n  while (Buffer.byteLength(truncated, \"utf8\") > maxBytes && truncated.length > 0) {\n    truncated = truncated.slice(0, Math.floor(truncated.length * 0.9));\n  }\n  return truncated;\n}"
      },
