        "sourceSlice": "function typeForTs(field: MakeFieldSpec): string {\n  if (field.type === \"number\" || field.type === \"integer\") {\n    return \"number\";\n  }\n  if (field.type === \"boolean\") {\n    return \"boolean\";\n  }\n  if (field.type === \"json\") {\n    return \"unknown\";\n  }\n  if (field.type === \"enum\") {\n    return (field.enumValues ?? []).map((value) => JSON.stringify(value)).join(\" | \") || \"string\";\n  }\n  return \"string\";\n}"
