        "fileContentHash": "373496c4e054a7f11e11f32391f6036bb0f371c2616157d7d00f489ebdc747b0",
        "sourceSlice": "function viteBridgeUsesLocalAbsoluteUrl(workspaceRoot: string, webRoot: string): string | null {\n  const root = normalize(webRoot);\n  const candidates = [\n    `${root}/src/lib/forge.ts`,\n    `${root}/src/lib/forge.tsx`,\n    `${root}/lib/forge.ts`,\n    `${root}/lib/forge.tsx`,\n  ];\n  for (const candidate of candidates) {\n    const text = readText(workspaceRoot, candidate);\n    if (!text) {\n      continue;\n    }\n    if (/export\\s+const\\s+forgeUrl[\\s\\S]*127\\.0\\.0\\.1:3765/.test(text) && !/useSameOrigin/.test(text)) {\n      return candidate;\n    }\n  }\n  return null;\n}"
