        "sourceSlice": "function webAuthSessionProxyConfigured(workspaceRoot: string): boolean {\n  const configText = [\n    \"web/vite.config.ts\",\n    \"web/vite.config.mts\",\n    \"web/vite.config.js\",\n    \"web/vite.config.mjs\",\n    \"web/next.config.ts\",\n    \"web/next.config.mjs\",\n    \"web/next.config.js\",\n  ].map((path) => readText(workspaceRoot, path)).join(\"\\n\");\n  if (!configText.trim()) {\n    return false;\n  }\n  return includesAll(configText, [\"/login\", \"/callback\", \"/logout\", \"/session\"]);\n}"
