        "fileContentHash": "373496c4e054a7f11e11f32391f6036bb0f371c2616157d7d00f489ebdc747b0",
        "sourceSlice": "function webConfigProxiesWorkOSSession(workspaceRoot: string, webRoot: string): boolean {\n  const root = normalize(webRoot);\n  const configText = [\n    `${root}/vite.config.ts`,\n    `${root}/vite.config.js`,\n    `${root}/vite.config.mts`,\n    `${root}/vite.config.mjs`,\n    `${root}/next.config.ts`,\n    `${root}/next.config.js`,\n    `${root}/next.config.mjs`,\n  ].map((path) => readText(workspaceRoot, path)).join(\"\\n\");\n  if (!configText.trim()) {\n    return false;\n  }\n  return [\"/login\", \"/callback\", \"/logout\", \"/session\"].every((route) =>\n    new RegExp(`[\"'\\`]${route.replace(\"/\", \"\\\\/\")}[\"'\\`]`).test(configText) ||\n    new RegExp(`source\\\\s*:\\\\s*[\"'\\`]${route.replace(\"/\", \"\\\\/\")}[\"'\\`]`).test(configText)\n  );\n}"
