      "file": "src/forge/cli/deploy.ts",
      "id": "ac11266fc5f1f23ad11ac04524ac80f970ee7af966279f2dfe7ae5fe020cc2f1",
      "kind": "code.function",
      "meta": {
        "exportPath": "",
        "fileContentHash": "348611c3be7f7fb82749372c82e2cca50f8fbe3d9ed6293cb38dd13d88334d59",
        "sourceSlice": "async function withDeployEnv<T>(workspaceRoot: string, fn: () => Promise<T>): Promise<T> {\n  const deployEnv = readDeployEnvFile(workspaceRoot);\n  const previous = new Map<string, string | undefined>();\n  for (const [name, value] of Object.entries(deployEnv)) {\n    if (process.env[name]) continue;\n    previous.set(name, process.env[name]);\n    process.env[name] = value;\n  }\n  try {\n    return await fn();\n  } finally {\n    for (const [name, value] of previous) {\n      if (value === undefined) {\n        delete process.env[name];\n      } else {\n        process.env[name] = value;\n      }\n    }\n  }\n}"
      },
