        "sourceSlice": "function workspaceChangeClassifier(workspaceRoot: string): ChangeClassifier {\n  const cache = new Map<string, ReturnType<ChangeClassifier>>();\n  return (file) => {\n    const cached = cache.get(file);\n    if (cached) {\n      return cached;\n    }\n    const baseType = classifyChangeType(file);\n    const type = baseType === \"docs\" && generatedMetadataOnlyChange(workspaceRoot, file)\n      ? \"generated\"\n      : baseType;\n    cache.set(file, type);\n    return type;\n  };\n}"
